package com.runejourney;

import com.runejourney.service.*;
import java.util.*;
import javax.inject.*;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.DBTableID;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
class AchievementsReader
{
	private static final int[] ENUM_CA_TIERS = {3981, 3982, 3983, 3984, 3985, 3986};
	private static final int PARAM_CA_ID = 1306;
	private static final int PARAM_CA_NAME = 1308;
	private static final int PARAM_CA_DESCRIPTION = 1309;
	private static final int PARAM_CA_TYPE = 1311;
	private static final int PARAM_CA_MONSTER = 1312;
	private static final int MAX_TASK_ID = RuneJourneyPlugin.CA_TASK_VARPS.length * 32 - 1;
	private static final int ENUM_CA_TYPES = 3969;
	private static final int ENUM_CA_MONSTERS = 3971;
	private static final int QUEST_TYPE_MINIQUEST = 1;

	private static final int REFRESH_TICKS = 100;

	@Inject
	private Client client;

	@Inject
	private JourneyService service;

	@Inject
	private RuneJourneyConfig config;

	private List<PublicAchievements.CombatTask> tasks;
	private Map<Quest, QuestInfo> questInfo;
	private boolean due = true;
	private int ticksSinceRead;

	@Value
	private static class QuestInfo
	{
		String sortName;
		int points;
		boolean members;
		boolean miniquest;
		Quest parent;
	}

	void refresh()
	{
		due = true;
	}

	void onGameTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN || !service.isBaselineSet() || !config.cloudSync())
		{
			return;
		}
		if (!due && ++ticksSinceRead < REFRESH_TICKS)
		{
			return;
		}
		due = false;
		ticksSinceRead = 0;
		try
		{
			service.onAchievements(quests(), combatTasks());
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read quests and combat tasks", e);
		}
	}

	private List<PublicAchievements.Quest> quests()
	{
		if (questInfo == null)
		{
			questInfo = readQuestInfo();
		}
		List<Quest> order = new ArrayList<>(questInfo.keySet());
		order.sort(Comparator.<Quest, String>comparing(q -> sortName(top(q)))
			.thenComparing(q -> questInfo.get(q).getParent() != null)
			.thenComparingInt(Quest::getId));

		List<PublicAchievements.Quest> out = new ArrayList<>();
		for (Quest q : order)
		{
			QuestInfo info = questInfo.get(q);
			out.add(new PublicAchievements.Quest(text(q.getName(), 100), state(q), Math.max(0, Math.min(100, info.getPoints())),
				info.isMembers(), info.isMiniquest(), info.getParent() == null ? null : text(info.getParent().getName(), 100)));
		}
		return out;
	}

	private Map<Quest, QuestInfo> readQuestInfo()
	{
		Map<Integer, Quest> byRow = new HashMap<>();
		for (Quest q : Quest.values())
		{
			byRow.put(q.getId(), q);
		}
		Map<Quest, QuestInfo> out = new EnumMap<>(Quest.class);
		for (Quest q : Quest.values())
		{
			int row = q.getId();
			try
			{
				Object sortName = field(row, DBTableID.Quest.COL_SORTNAME);
				Object parent = field(row, DBTableID.Quest.COL_PARENT_QUEST);
				out.put(q, new QuestInfo(
					sortName instanceof String ? (String) sortName : q.getName(),
					number(field(row, DBTableID.Quest.COL_QUESTPOINTS)),
					number(field(row, DBTableID.Quest.COL_MEMBERS)) != 0,
					number(field(row, DBTableID.Quest.COL_TYPE)) == QUEST_TYPE_MINIQUEST,
					parent instanceof Integer ? byRow.get(parent) : null));
			}
			catch (RuntimeException e)
			{
				log.debug("Couldn't read quest {}", q, e);
				out.put(q, new QuestInfo(q.getName(), 0, false, false, null));
			}
		}
		return out;
	}

	private Quest top(Quest q)
	{
		Quest parent = questInfo.get(q).getParent();
		return parent != null && questInfo.containsKey(parent) ? parent : q;
	}

	private String sortName(Quest q)
	{
		return questInfo.get(q).getSortName();
	}

	private String state(Quest q)
	{
		switch (q.getState(client))
		{
			case FINISHED:
				return PublicAchievements.Quest.FINISHED;
			case IN_PROGRESS:
				return PublicAchievements.Quest.IN_PROGRESS;
			default:
				return PublicAchievements.Quest.NOT_STARTED;
		}
	}

	private Object field(int row, int column)
	{
		Object[] values = client.getDBTableField(row, column, 0);
		return values == null || values.length == 0 ? null : values[0];
	}

	private static int number(Object value)
	{
		if (value instanceof Integer)
		{
			return (Integer) value;
		}
		return Boolean.TRUE.equals(value) ? 1 : 0;
	}

	private List<PublicAchievements.CombatTask> combatTasks()
	{
		if (tasks == null)
		{
			tasks = readTasks();
		}
		int[] completed = new int[RuneJourneyPlugin.CA_TASK_VARPS.length];
		for (int i = 0; i < completed.length; i++)
		{
			completed[i] = client.getVarpValue(RuneJourneyPlugin.CA_TASK_VARPS[i]);
		}
		List<PublicAchievements.CombatTask> out = new ArrayList<>(tasks.size());
		for (PublicAchievements.CombatTask t : tasks)
		{
			int varp = t.getId() / 32;
			boolean done = varp < completed.length && (completed[varp] & (1 << (t.getId() % 32))) != 0;
			out.add(new PublicAchievements.CombatTask(t.getId(), t.getName(), t.getDescription(), t.getTier(), t.getType(), t.getMonster(), done));
		}
		return out;
	}

	private List<PublicAchievements.CombatTask> readTasks()
	{
		EnumComposition types = client.getEnum(ENUM_CA_TYPES);
		EnumComposition monsters = client.getEnum(ENUM_CA_MONSTERS);
		List<PublicAchievements.CombatTask> out = new ArrayList<>();
		for (int t = 0; t < ENUM_CA_TIERS.length; t++)
		{
			for (int structId : client.getEnum(ENUM_CA_TIERS[t]).getIntVals())
			{
				StructComposition s = client.getStructComposition(structId);
				int id = s.getIntValue(PARAM_CA_ID);
				String name = text(s.getStringValue(PARAM_CA_NAME), 100);
				if (id < 0 || id > MAX_TASK_ID || name.isEmpty())
				{
					continue;
				}
				String type = text(types.getStringValue(s.getIntValue(PARAM_CA_TYPE)), 40);
				String monster = text(monsters.getStringValue(s.getIntValue(PARAM_CA_MONSTER)), 100);
				out.add(new PublicAchievements.CombatTask(
					id,
					name,
					text(s.getStringValue(PARAM_CA_DESCRIPTION), 300),
					t + 1,
					type.isEmpty() ? "Other" : type,
					monster.isEmpty() ? "None" : monster,
					false));
			}
		}
		return out;
	}

	static String text(String value, int max)
	{
		if (value == null)
		{
			return "";
		}
		String clean = Text.removeTags(value.replace("<br>", " "))
			.replaceAll("[\\p{Cntrl}<>]", " ")
			.replaceAll("\\s+", " ")
			.trim();
		return clean.length() > max ? clean.substring(0, max).trim() : clean;
	}
}

package com.runejourney;

import com.runejourney.cloud.*;
import com.runejourney.model.ClogItem;
import com.runejourney.service.JourneyService;
import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
class CollectionLogSync
{
	private static final int SCRIPT_SETUP = 7797;
	private static final int SCRIPT_DRAW_ITEM = 4100;
	private static final int SCRIPT_SEARCH_CLOSE = 2240;
	private static final int ENUM_TABS = 2102;
	private static final int PARAM_TAB_NAME = 682;
	private static final int PARAM_TAB_PAGES = 683;
	private static final int PARAM_PAGE_NAME = 689;
	private static final int PARAM_PAGE_ITEMS = 690;
	private static final int ENUM_REPLACEMENTS = 3721;

	private static final int QUIET_TICKS = 2;
	private static final int MAX_TICKS = 10;
	private static final int SCRIPT_MENU_CLOSE = 7813;
	private static final String MENU_TEXT = "RuneJourney";
	private static final int MENU_COLOUR = 0xff981f;
	private static final int MENU_COLOUR_HOVERED = 0xffffff;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private JourneyService service;

	@Inject
	private SyncManager sync;

	@Inject
	private RuneJourneyConfig config;

	private final Map<Integer, Integer> captured = new HashMap<>();
	private boolean capturing;
	private int ticksCapturing;
	private int ticksSinceItem;

	void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == SCRIPT_SETUP && allowed())
		{
			clientThread.invokeLater(this::addMenuOption);
		}
	}

	void onScriptPreFired(ScriptPreFired event)
	{
		if (!capturing || event.getScriptId() != SCRIPT_DRAW_ITEM || event.getScriptEvent() == null)
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		int itemId = (Integer) args[1];
		int quantity = (Integer) args[2];
		if (itemId > 0 && quantity > 0)
		{
			captured.merge(itemId, quantity, Math::max);
			ticksSinceItem = 0;
		}
	}

	void onGameTick()
	{
		if (!capturing)
		{
			return;
		}
		ticksCapturing++;
		ticksSinceItem++;
		if ((!captured.isEmpty() && ticksSinceItem >= QUIET_TICKS) || ticksCapturing >= MAX_TICKS)
		{
			capturing = false;
			finish();
		}
	}

	void reset()
	{
		capturing = false;
		captured.clear();
	}

	private boolean allowed()
	{
		CloudStatus status = sync.status();
		return config.cloudSync() && status.getConnection() == CloudStatus.Connection.CONNECTED && status.isLinked();
	}

	private void start()
	{
		if (capturing || client.getWidget(InterfaceID.Collection.SEARCH_TOGGLE) == null)
		{
			return;
		}
		captured.clear();
		capturing = true;
		ticksCapturing = 0;
		ticksSinceItem = 0;
		service.say("Syncing your collection log with RuneJourney...");
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(SCRIPT_SEARCH_CLOSE);
	}

	private void finish()
	{
		if (captured.isEmpty())
		{
			service.say("Couldn't read your collection log. Try the RuneJourney button again.");
			return;
		}
		Map<Integer, Integer> replacements = new HashMap<>();
		EnumComposition replaced = client.getEnum(ENUM_REPLACEMENTS);
		for (int i = 0; i < replaced.getKeys().length; i++)
		{
			replacements.put(replaced.getKeys()[i], replaced.getIntVals()[i]);
		}

		Map<String, List<String>> tabs = new LinkedHashMap<>();
		Map<String, List<ClogItem>> pages = new LinkedHashMap<>();
		Map<Integer, Boolean> unique = new HashMap<>();
		for (int tabId : client.getEnum(ENUM_TABS).getIntVals())
		{
			StructComposition tab = client.getStructComposition(tabId);
			List<String> pageNames = new ArrayList<>();
			for (int pageId : client.getEnum(tab.getIntValue(PARAM_TAB_PAGES)).getIntVals())
			{
				StructComposition page = client.getStructComposition(pageId);
				String pageName = page.getStringValue(PARAM_PAGE_NAME);
				List<ClogItem> items = new ArrayList<>();
				for (int listed : client.getEnum(page.getIntValue(PARAM_PAGE_ITEMS)).getIntVals())
				{
					int id = replacements.getOrDefault(listed, listed);
					int quantity = captured.getOrDefault(id, 0);
					items.add(new ClogItem(id, itemManager.getItemComposition(id).getName(), quantity > 0, quantity));
					unique.merge(id, quantity > 0, Boolean::logicalOr);
				}
				pageNames.add(pageName);
				pages.put(pageName, items);
			}
			tabs.put(tab.getStringValue(PARAM_TAB_NAME), pageNames);
		}
		if (pages.isEmpty())
		{
			service.say("Couldn't read your collection log. Try the RuneJourney button again.");
			return;
		}
		service.onCollectionLog(tabs, pages);
		long obtained = unique.values().stream().filter(b -> b).count();
		service.say(String.format("Collection log saved: %,d of %,d items. It'll show on your public page after the next sync.", obtained, unique.size()));
		sync.syncNow();
	}

	private void addMenuOption()
	{
		Widget frame = client.getWidget(InterfaceID.Collection.BURGER_MENU_FRAME);
		Widget[] children = frame == null ? null : frame.getDynamicChildren();
		if (children == null)
		{
			return;
		}
		Widget first = null;
		Widget last = null;
		Widget ours = null;
		for (Widget w : children)
		{
			if (w == null || w.getType() != WidgetType.TEXT)
			{
				continue;
			}
			if (MENU_TEXT.equals(w.getText()))
			{
				ours = w;
			}
			else
			{
				first = first == null || w.getOriginalY() < first.getOriginalY() ? w : first;
				last = last == null || w.getOriginalY() > last.getOriginalY() ? w : last;
			}
		}
		if (last == null)
		{
			return;
		}

		int y = last.getOriginalY() + last.getOriginalHeight();
		if (ours == null)
		{
			Widget option = frame.createChild(-1, WidgetType.TEXT);
			option.setText(MENU_TEXT);
			option.setTextColor(MENU_COLOUR);
			option.setHasListener(true);
			option.setOnMouseOverListener((JavaScriptCallback) e -> option.setTextColor(MENU_COLOUR_HOVERED));
			option.setOnMouseLeaveListener((JavaScriptCallback) e -> option.setTextColor(MENU_COLOUR));
			option.setAction(0, "Sync with RuneJourney");
			option.setOnOpListener((JavaScriptCallback) e ->
			{
				client.runScript(SCRIPT_MENU_CLOSE, InterfaceID.Collection.BURGER_BTN_MENU,
					InterfaceID.Collection.BURGER_MENU_FRAME, InterfaceID.Collection.BURGER_MENU_OVERLAY);
				start();
			});
			ours = option;
		}
		ours.setFontId(last.getFontId())
			.setTextShadowed(last.getTextShadowed())
			.setXTextAlignment(last.getXTextAlignment())
			.setYTextAlignment(last.getYTextAlignment())
			.setXPositionMode(last.getXPositionMode())
			.setYPositionMode(last.getYPositionMode())
			.setPos(last.getOriginalX(), y)
			.setSize(last.getOriginalWidth(), last.getOriginalHeight());

		frame.setOriginalHeight(y + last.getOriginalHeight() + first.getOriginalY());
		frame.revalidate();
		for (Widget w : frame.getDynamicChildren())
		{
			if (w != null)
			{
				w.revalidate();
			}
		}
	}
}

package com.runejourney;

import com.runejourney.service.JourneyService;
import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
class IncomeTracker
{
	private enum Outcome
	{
		COUNTED,
		UNMATCHED,
		SKIPPED
	}

	private static final Set<Skill> COMBAT = EnumSet.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS,
		Skill.RANGED, Skill.SLAYER);
	private static final Set<Integer> BLOCKING_INTERFACES = new HashSet<>();
	private static final int BLOCK_GRACE_TICKS = 2;

	static
	{
		BLOCKING_INTERFACES.add(InterfaceID.BANKMAIN);
		BLOCKING_INTERFACES.add(InterfaceID.BANK_DEPOSITBOX);
		BLOCKING_INTERFACES.add(InterfaceID.GE_OFFERS);
		BLOCKING_INTERFACES.add(InterfaceID.GE_COLLECT);
		BLOCKING_INTERFACES.add(InterfaceID.SHOPMAIN);
		BLOCKING_INTERFACES.add(InterfaceID.TRADEMAIN);
		BLOCKING_INTERFACES.add(InterfaceID.TRADECONFIRM);
	}

	private final ItemManager itemManager;
	private final JourneyService service;

	private Map<Integer, Integer> lastInventory;
	private final Map<Integer, Integer> pendingDelta = new HashMap<>();
	private final Map<Skill, Long> pendingXp = new EnumMap<>(Skill.class);
	private final Map<Integer, Integer> carriedDelta = new HashMap<>();
	private final Map<Skill, Long> carriedXp = new EnumMap<>(Skill.class);
	private final Set<Integer> openBlocking = new HashSet<>();
	private int blockedUntil;
	private int suppressedTick = -1;

	@Inject
	IncomeTracker(ItemManager itemManager, JourneyService service)
	{
		this.itemManager = itemManager;
		this.service = service;
	}

	void reset()
	{
		lastInventory = null;
		pendingDelta.clear();
		pendingXp.clear();
		carriedDelta.clear();
		carriedXp.clear();
		openBlocking.clear();
		blockedUntil = 0;
		suppressedTick = -1;
	}

	void onInventory(ItemContainer container)
	{
		Map<Integer, Integer> now = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				now.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		if (lastInventory != null)
		{
			Set<Integer> ids = new HashSet<>(now.keySet());
			ids.addAll(lastInventory.keySet());
			for (int id : ids)
			{
				int change = now.getOrDefault(id, 0) - lastInventory.getOrDefault(id, 0);
				if (change != 0)
				{
					pendingDelta.merge(id, change, Integer::sum);
				}
			}
		}
		lastInventory = now;
	}

	void discard(Map<Integer, Integer> changes)
	{
		changes.forEach((id, change) -> pendingDelta.merge(id, -change, Integer::sum));
	}

	void onXp(Skill skill, long delta)
	{
		if (delta > 0)
		{
			pendingXp.merge(skill, delta, Long::sum);
		}
	}

	void onInterfaceOpened(int groupId)
	{
		if (BLOCKING_INTERFACES.contains(groupId))
		{
			openBlocking.add(groupId);
		}
	}

	void onInterfaceClosed(int groupId, int tick)
	{
		if (openBlocking.remove(groupId))
		{
			blockedUntil = tick + BLOCK_GRACE_TICKS;
		}
	}

	void suppress(int tick)
	{
		suppressedTick = tick;
	}

	void onTick(int tick)
	{
		boolean carried = !carriedDelta.isEmpty() || !carriedXp.isEmpty();
		carriedDelta.forEach((id, change) -> pendingDelta.merge(id, change, Integer::sum));
		carriedXp.forEach((skill, xp) -> pendingXp.merge(skill, xp, Long::sum));
		carriedDelta.clear();
		carriedXp.clear();
		try
		{
			if (process(tick) == Outcome.UNMATCHED && !carried)
			{
				carriedDelta.putAll(pendingDelta);
				carriedXp.putAll(pendingXp);
			}
		}
		finally
		{
			pendingDelta.clear();
			pendingXp.clear();
		}
	}

	private Outcome process(int tick)
	{
		pendingDelta.values().removeIf(v -> v == 0);
		if ((pendingDelta.isEmpty() && pendingXp.isEmpty()) || !openBlocking.isEmpty() || tick <= blockedUntil
			|| suppressedTick >= tick - 1)
		{
			return Outcome.SKIPPED;
		}
		if (pendingDelta.isEmpty())
		{
			return isCombat(pendingXp.keySet()) ? Outcome.SKIPPED : Outcome.UNMATCHED;
		}

		long coinsGained = 0;
		boolean pouchOpened = false;
		List<SkillingRules.Change> changes = new ArrayList<>();
		Map<String, Integer> ids = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : pendingDelta.entrySet())
		{
			int id = e.getKey();
			int qty = e.getValue();
			String name = itemManager.getItemComposition(id).getName();
			long price = id == ItemID.COINS ? 1 : id == ItemID.PLATINUM ? 1000 : itemManager.getItemPrice(id);
			changes.add(new SkillingRules.Change(name, qty, price));
			ids.put(name, id);
			if (qty > 0 && id == ItemID.COINS)
			{
				coinsGained += qty;
			}
			if (qty < 0 && name != null && name.toLowerCase(Locale.ENGLISH).contains("coin pouch"))
			{
				pouchOpened = true;
			}
		}

		if (pendingXp.isEmpty())
		{
			if (pouchOpened && coinsGained > 0)
			{
				service.onSkillingIncome(Skill.THIEVING, coinsGained,
					Collections.singletonList(new JourneyService.LootItem(ItemID.COINS, "Coins", (int) coinsGained, coinsGained)));
				return Outcome.COUNTED;
			}
			return Outcome.UNMATCHED;
		}
		if (isCombat(pendingXp.keySet()))
		{
			return Outcome.SKIPPED;
		}

		List<Skill> skills = new ArrayList<>(pendingXp.keySet());
		skills.sort((a, b) -> Long.compare(pendingXp.get(b), pendingXp.get(a)));
		SkillingRules.Income income = SkillingRules.evaluate(skills, changes);
		log.debug("Tick {}: XP {}, items {} -> {}", tick, pendingXp, changes, income);
		if (income == null)
		{
			return Outcome.UNMATCHED;
		}
		List<JourneyService.LootItem> products = new ArrayList<>();
		for (SkillingRules.Change c : income.getProducts())
		{
			products.add(new JourneyService.LootItem(ids.getOrDefault(c.getName(), -1), c.getName(), c.getQuantity(),
				c.getUnitPrice() * c.getQuantity()));
		}
		service.onSkillingIncome(income.getSkill(), income.getValue(), products);
		return Outcome.COUNTED;
	}

	static boolean isCombat(Set<Skill> skills)
	{
		for (Skill s : skills)
		{
			if (COMBAT.contains(s) && !(s == Skill.STRENGTH && skills.contains(Skill.FISHING)))
			{
				return true;
			}
		}
		return false;
	}
}

package com.runejourney;

import com.runejourney.planner.Intensity;
import net.runelite.client.config.*;

@ConfigGroup(RuneJourneyConfig.GROUP)
public interface RuneJourneyConfig extends Config
{
	String GROUP = "runejourney";

	@ConfigSection(
		name = "Journey",
		description = "What gets recorded in your Journey",
		position = 0
	)
	String journeySection = "journey";

	@ConfigSection(
		name = "Screenshots",
		description = "Automatically capture screenshots of important moments",
		position = 1
	)
