		PublicAchievements a = new PublicAchievements();
		a.setSyncedAt(Instant.now().atOffset(ZoneOffset.UTC).withNano(0).toString());
		a.setQuests(new ArrayList<>(quests));
		a.setCombatTasks(new ArrayList<>(tasks));
		achievements = a;
	}

