	private String sourceWithKc(String source)
	{
		if (source == null)
		{
			return "Unknown source";
		}
		if (source.equalsIgnoreCase(lastKcBoss) && currentTick - lastKcTick <= LOOT_WINDOW_TICKS)
		{
