	@Override
	public synchronized double hours(Skill skill, long fromXp, long toXp)
	{
		if (toXp <= fromXp)
		{
			return 0;
		}
		SavedMethod saved = savedMethod(skill);
		if (saved != null)
		{
			return (toXp - fromXp) / saved.xpPerHour();
