package com.runejourney.sync;

import com.google.gson.*;
import com.runejourney.model.*;
import java.util.*;
import java.util.function.Function;

public final class DaySlices
{
	public static final Set<String> ADDITIVE = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"playMillis", "xpGained", "skillXp", "levelsGained", "lootValue", "bossKills", "deaths", "collectionLogSlots",
		"questsCompleted", "personalBests", "slayerTasks", "cluesCompleted", "pets", "clues", "clueLootValue",
		"skillingIncome", "offlineXp", "offlineSkillXp", "awayXp", "awaySkillXp", "awayLevels", "skillingIncomeBySkill",
		"lootBySource", "suppliesCost", "suppliesUsed", "combatTasks", "combatTaskPoints")));
	public static final Set<String> SPECIAL = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"date", "awayFrom", "xpRanges", "offlineRanges", "awayRanges", "snapshot", "events", "sync")));

	private DaySlices()
	{
	}

	public static DayRecord combine(Gson gson, String date, Map<String, DaySlice> slices)
	{
		List<String> devices = devices(slices);
		JsonObject counts = new JsonObject();
		for (String device : devices)
		{
			Trees.add(counts, counts(gson, slices.get(device).getDay()), 1);
		}
		Trees.prune(counts);
		DayRecord d = gson.fromJson(counts, DayRecord.class);
		d.setDate(date);

		DaySlice snapshotFrom = null;
		for (String device : devices)
		{
			DaySlice slice = slices.get(device);
			DayRecord part = slice.getDay();
			d.setXpRanges(XpRanges.union(d.getXpRanges(), part.getXpRanges()));
			d.setOfflineRanges(XpRanges.union(d.getOfflineRanges(), part.getOfflineRanges()));
			d.setAwayRanges(XpRanges.union(d.getAwayRanges(), part.getAwayRanges()));
			d.setAwayFrom(earliest(d.getAwayFrom(), part.getAwayFrom()));
			if (snapshotFrom == null || slice.getSnapshotClock() > snapshotFrom.getSnapshotClock()
				|| (slice.getSnapshotClock() == snapshotFrom.getSnapshotClock() && snapshotFrom.getDay().getSnapshot().isEmpty()))
			{
				snapshotFrom = slice;
			}
		}
		if (snapshotFrom != null)
		{
			d.setSnapshot(new HashMap<>(snapshotFrom.getDay().getSnapshot()));
		}
		d.setEvents(events(devices, slices));
		return d;
	}

	public static DaySlice reconcile(Gson gson, DayRecord view, String me, Map<String, DaySlice> slices, Hlc hlc)
	{
		DaySlice own = slices.get(me);
		if (own != null && own.getDay() == null)
		{
			own = null;
		}
		DayRecord ownDay = own != null ? own.getDay() : new DayRecord(view.getDate());
		Map<String, DaySlice> remotes = new HashMap<>();
		slices.forEach((device, slice) ->
		{
			if (!device.equals(me) && slice != null && slice.getDay() != null)
			{
				remotes.put(device, slice);
			}
		});
		DayRecord base = combine(gson, view.getDate(), slices);

		JsonObject counts = counts(gson, view);
		for (DaySlice r : remotes.values())
		{
			Trees.add(counts, counts(gson, r.getDay()), -1);
		}
		Trees.prune(counts);
		DayRecord day = gson.fromJson(counts, DayRecord.class);
		day.setDate(view.getDate());

		day.setXpRanges(mine(view, ownDay, remotes, DayRecord::getXpRanges));
		day.setOfflineRanges(mine(view, ownDay, remotes, DayRecord::getOfflineRanges));
		day.setAwayRanges(mine(view, ownDay, remotes, DayRecord::getAwayRanges));

		String awayFrom = ownDay.getAwayFrom();
		if (!Objects.equals(view.getAwayFrom(), base.getAwayFrom()) || (awayFrom == null && day.getAwayXp() > ownDay.getAwayXp()))
		{
			awayFrom = earliest(awayFrom, view.getAwayFrom());
		}
		day.setAwayFrom(awayFrom);

		DaySlice next = new DaySlice();
		if (!view.getSnapshot().equals(base.getSnapshot()))
		{
			day.setSnapshot(new HashMap<>(view.getSnapshot()));
			next.setSnapshotClock(hlc.next());
		}
		else
		{
			day.setSnapshot(new HashMap<>(ownDay.getSnapshot()));
			next.setSnapshotClock(own != null ? own.getSnapshotClock() : 0);
		}

		if (own != null)
		{
			next.getNotes().putAll(own.getNotes());
			next.getDeleted().addAll(own.getDeleted());
			next.getScreenshotsDeleted().addAll(own.getScreenshotsDeleted());
		}
		Map<String, JourneyEvent> before = byId(base.getEvents());
		Set<String> remoteIds = new HashSet<>();
		remotes.values().forEach(r -> r.getDay().getEvents().forEach(e -> remoteIds.add(e.getId())));
		Set<String> kept = new HashSet<>();
		List<JourneyEvent> events = new ArrayList<>();
		for (JourneyEvent e : view.getEvents())
		{
			if (e.getId() == null)
			{
				continue;
			}
			kept.add(e.getId());
			if (!remoteIds.contains(e.getId()) || me.equals(owner(e.getId(), slices)))
			{
				JourneyEvent c = e.copy();
				c.setNote(null);
				events.add(c);
			}
			JourneyEvent was = before.get(e.getId());
			if (!Objects.equals(e.getNote(), was != null ? was.getNote() : null))
			{
				next.getNotes().put(e.getId(), new NoteEdit(e.getNote(), hlc.next()));
			}
			if (was != null && was.getScreenshot() != null && e.getScreenshot() == null)
			{
				next.getScreenshotsDeleted().add(e.getId());
			}
		}
		for (JourneyEvent e : base.getEvents())
		{
			if (!kept.contains(e.getId()))
			{
				next.getDeleted().add(e.getId());
			}
		}
		day.setEvents(events);
		next.setDay(day);
		return next;
	}

	public static boolean matches(Gson gson, DayRecord view, Map<String, DaySlice> slices)
	{
		DayRecord combined = combine(gson, view.getDate(), slices);
		JsonObject a = counts(gson, view);
		Trees.prune(a);
		JsonObject b = counts(gson, combined);
		Trees.prune(b);
		if (!a.equals(b)
			|| !XpRanges.same(view.getXpRanges(), combined.getXpRanges())
			|| !XpRanges.same(view.getOfflineRanges(), combined.getOfflineRanges())
			|| !XpRanges.same(view.getAwayRanges(), combined.getAwayRanges())
			|| !Objects.equals(view.getAwayFrom(), combined.getAwayFrom())
			|| !view.getSnapshot().equals(combined.getSnapshot())
			|| view.getEvents().size() != combined.getEvents().size())
		{
			return false;
		}
		Map<String, JourneyEvent> mine = byId(view.getEvents());
		for (JourneyEvent e : combined.getEvents())
		{
			if (!e.equals(mine.get(e.getId())))
			{
				return false;
			}
		}
		return true;
	}

	public static Map<String, Set<String>> trim(Map<String, Map<String, DaySlice>> byDate)
	{
		Map<String, List<Claim>> claims = new HashMap<>();
		byDate.forEach((date, slices) -> slices.forEach((device, slice) ->
		{
			DayRecord d = slice.getDay();
			if (d == null)
			{
				return;
			}
			d.getOfflineRanges().forEach((skill, list) -> list.forEach(r ->
				claims.computeIfAbsent(skill, k -> new ArrayList<>()).add(new Claim(date, device, false, skill, r, slice))));
			d.getAwayRanges().forEach((skill, list) -> list.forEach(r ->
				claims.computeIfAbsent(skill, k -> new ArrayList<>()).add(new Claim(date, device, true, skill, r, slice))));
		}));
		Map<String, Set<String>> changed = new TreeMap<>();
		if (claims.isEmpty())
		{
			return changed;
		}

		Map<String, List<long[]>> online = new HashMap<>();
		byDate.values().forEach(slices -> slices.values().forEach(slice ->
		{
			if (slice.getDay() != null)
			{
				slice.getDay().getXpRanges().forEach((skill, list) ->
				{
					if (claims.containsKey(skill))
					{
						online.computeIfAbsent(skill, k -> new ArrayList<>()).addAll(list);
					}
				});
			}
		}));

		Map<long[], List<long[]>> keep = new IdentityHashMap<>();
		Map<long[], Claim> trimmed = new IdentityHashMap<>();
		claims.forEach((skill, list) ->
		{
			list.sort(Comparator.comparing((Claim c) -> c.date).thenComparing(c -> c.device)
				.thenComparing(c -> c.away).thenComparingLong(c -> c.range[0]));
			List<long[]> covered = XpRanges.normalize(online.getOrDefault(skill, Collections.emptyList()));
			for (Claim c : list)
			{
				List<long[]> left = XpRanges.subtract(Collections.singletonList(c.range), covered);
				covered = XpRanges.union(covered, Collections.singletonList(c.range));
				if (XpRanges.length(left) != c.range[1] - c.range[0])
				{
					keep.put(c.range, left);
					trimmed.put(c.range, c);
				}
			}
		});

		Map<DaySlice, Set<String>> done = new IdentityHashMap<>();
		for (Claim c : trimmed.values())
		{
			Map<String, List<long[]>> ranges = c.away ? c.slice.getDay().getAwayRanges() : c.slice.getDay().getOfflineRanges();
			if (!done.computeIfAbsent(c.slice, k -> new HashSet<>()).add(c.away + "|" + c.skill))
			{
				continue;
			}
			List<long[]> was = ranges.get(c.skill);
			List<long[]> now = new ArrayList<>();
			for (long[] r : was)
			{
				now.addAll(keep.getOrDefault(r, Collections.singletonList(r)));
			}
			long xp = XpRanges.length(was) - XpRanges.length(now);
			int levels = XpRanges.levels(was) - XpRanges.levels(now);
			if (now.isEmpty())
			{
				ranges.remove(c.skill);
			}
			else
			{
				ranges.put(c.skill, now);
			}
			dropFound(c.slice.getDay(), c.away, c.skill, xp, levels);
			changed.computeIfAbsent(c.date, k -> new HashSet<>()).add(c.device);
		}
		return changed;
	}

	private static class Claim
	{
		final String date;
		final String device;
		final boolean away;
		final String skill;
		final long[] range;
		final DaySlice slice;

		Claim(String date, String device, boolean away, String skill, long[] range, DaySlice slice)
		{
			this.date = date;
			this.device = device;
			this.away = away;
			this.skill = skill;
			this.range = range;
			this.slice = slice;
		}
	}

	private static void dropFound(DayRecord d, boolean away, String skill, long xp, int levels)
	{
		if (away)
		{
			d.setAwayXp(d.getAwayXp() - xp);
			reduce(d.getAwaySkillXp(), skill, xp);
			d.setAwayLevels(Math.max(0, d.getAwayLevels() - levels));
		}
		else
		{
			d.setOfflineXp(d.getOfflineXp() - xp);
			reduce(d.getOfflineSkillXp(), skill, xp);
			d.setXpGained(d.getXpGained() - xp);
			reduce(d.getSkillXp(), skill, xp);
			d.setLevelsGained(Math.max(0, d.getLevelsGained() - levels));
		}
	}

	private static void reduce(Map<String, Long> xp, String skill, long by)
	{
		xp.computeIfPresent(skill, (k, v) -> v - by > 0 ? v - by : null);
	}

	private static List<JourneyEvent> events(List<String> devices, Map<String, DaySlice> slices)
	{
		Set<String> deleted = new HashSet<>();
		Set<String> shotsDeleted = new HashSet<>();
		Map<String, NoteEdit> notes = new HashMap<>();
		for (String device : devices)
		{
			DaySlice s = slices.get(device);
			deleted.addAll(s.getDeleted());
			shotsDeleted.addAll(s.getScreenshotsDeleted());
			s.getNotes().forEach((id, edit) ->
			{
				NoteEdit best = notes.get(id);
				if (best == null || edit.getClock() > best.getClock())
				{
					notes.put(id, edit);
				}
			});
		}

		Map<String, JourneyEvent> shown = new LinkedHashMap<>();
		for (String device : devices)
		{
			for (JourneyEvent e : slices.get(device).getDay().getEvents())
			{
				if (e.getId() == null || deleted.contains(e.getId()))
				{
					continue;
				}
				JourneyEvent best = shown.get(e.getId());
				if (best == null || e.getTime() < best.getTime())
				{
					shown.put(e.getId(), e);
				}
			}
		}

		List<JourneyEvent> out = new ArrayList<>();
		for (JourneyEvent e : shown.values())
		{
			JourneyEvent c = e.copy();
			NoteEdit note = notes.get(e.getId());
			c.setNote(note != null ? note.getText() : null);
			if (shotsDeleted.contains(e.getId()))
			{
				c.setScreenshot(null);
			}
			out.add(c);
		}
		out.sort(Comparator.comparingLong(JourneyEvent::getTime).thenComparing(JourneyEvent::getId));
		return out;
	}

	private static String owner(String id, Map<String, DaySlice> slices)
	{
		String owner = null;
		long time = Long.MAX_VALUE;
		for (String device : devices(slices))
		{
			for (JourneyEvent e : slices.get(device).getDay().getEvents())
			{
				if (id.equals(e.getId()) && e.getTime() < time)
				{
					owner = device;
					time = e.getTime();
				}
			}
		}
		return owner;
	}

	private static Map<String, List<long[]>> mine(DayRecord view, DayRecord own, Map<String, DaySlice> remotes,
		Function<DayRecord, Map<String, List<long[]>>> kind)
	{
		Map<String, List<long[]>> others = new HashMap<>();
		for (DaySlice r : remotes.values())
		{
			others = XpRanges.union(others, kind.apply(r.getDay()));
		}
		return XpRanges.union(kind.apply(own), XpRanges.subtract(kind.apply(view), others));
	}

	private static JsonObject counts(Gson gson, DayRecord d)
	{
		return Trees.only(gson.toJsonTree(d).getAsJsonObject(), ADDITIVE);
	}

	private static Map<String, JourneyEvent> byId(List<JourneyEvent> events)
	{
		Map<String, JourneyEvent> out = new HashMap<>();
		for (JourneyEvent e : events)
		{
			if (e.getId() != null)
			{
				out.put(e.getId(), e);
			}
		}
		return out;
	}

	private static String earliest(String a, String b)
	{
		if (a == null)
		{
			return b;
		}
		return b == null || a.compareTo(b) <= 0 ? a : b;
	}

	private static List<String> devices(Map<String, DaySlice> slices)
	{
		List<String> devices = new ArrayList<>();
		slices.forEach((device, slice) ->
		{
			if (slice != null && slice.getDay() != null)
			{
				devices.add(device);
			}
		});
		Collections.sort(devices);
		return devices;
	}
}

package com.runejourney.sync;

import com.runejourney.model.*;
import lombok.Data;

public final class Envelope
{
	public static final int MAJOR = 1;
	public static final int MINOR = 0;
	public static final String SCHEMA = MAJOR + "." + MINOR;
	public static final String PROFILE = "profile";
	private static final String DAY_PREFIX = "day:";

	private Envelope()
	{
	}

	@Data
	public static class Doc
	{
		private String schema;
		private ProfileSlice profile;
		private DaySlice day;
	}

	public static boolean readable(String schema)
	{
		if (schema == null)
		{
			return false;
		}
		int dot = schema.indexOf('.');
		try
		{
			return Integer.parseInt(dot < 0 ? schema : schema.substring(0, dot)) <= MAJOR;
		}
		catch (NumberFormatException e)
		{
			return false;
		}
	}

	public static String dayKey(String date)
	{
		return DAY_PREFIX + date;
	}

	public static String dateOf(String docKey)
	{
		return docKey != null && docKey.startsWith(DAY_PREFIX) ? docKey.substring(DAY_PREFIX.length()) : null;
	}

	public static Doc profile(ProfileSlice slice)
	{
		Doc d = new Doc();
		d.setSchema(SCHEMA);
		d.setProfile(slice);
		return d;
	}

	public static Doc day(DaySlice slice)
	{
		Doc d = new Doc();
		d.setSchema(SCHEMA);
		d.setDay(slice);
		return d;
	}
}

package com.runejourney.sync;

import com.runejourney.model.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class EventIds
{
	private EventIds()
	{
	}

	public static String random()
	{
		return UUID.randomUUID().toString();
	}

	public static String fixed(Object... parts)
	{
		StringBuilder id = new StringBuilder();
		for (Object part : parts)
		{
			if (id.length() > 0)
			{
				id.append('|');
			}
			id.append(part);
		}
		return id.toString();
	}

	public static boolean assignMissing(DayRecord day)
	{
		boolean changed = false;
		Map<String, Integer> seen = new HashMap<>();
		for (JourneyEvent e : day.getEvents())
		{
			String content = day.getDate() + "\n" + e.getTime() + "\n" + e.getType() + "\n" + e.getTitle() + "\n" + e.getDetail();
			int n = seen.merge(content, 1, Integer::sum) - 1;
			if (e.getId() == null)
			{
				e.setId(UUID.nameUUIDFromBytes((content + "\n" + n).getBytes(StandardCharsets.UTF_8)).toString());
				changed = true;
			}
		}
		return changed;
	}
}

package com.runejourney.sync;

import com.google.gson.*;
import com.runejourney.model.ProfileSlice;
import java.util.*;

final class GoalJoin
{
	static final Set<String> SAME = keys("id", "type", "createdAt", "startXp", "startTotalLevel", "startCount");
	static final Set<String> SPEC = keys("name", "skill", "targetXp", "targetLevel", "targetDate", "hoursPerWeek", "notes",
		"counter", "targetCount", "relative", "quantity", "fixedPrice", "items");
	static final Set<String> PLAN = keys("weekStart", "weekStartXp", "weekTargets", "lastWeekResults", "weeksPlanned", "weeksMet",
		"planStreak", "bestPlanStreak");
	static final Set<String> DONE = keys("completedAt", "story");
	static final Set<String> ANY = keys("affordable");
	static final Set<String> SUM = keys("purchasedQuantity", "purchaseSpent");
	static final Set<String> ITEM_STATE = keys("obtainedAt", "source");

	private GoalJoin()
	{
	}

	static JsonArray combine(List<String> devices, Map<String, JsonArray> goals, Map<String, ProfileSlice> slices)
	{
		Set<String> deleted = new HashSet<>();
		devices.forEach(d -> deleted.addAll(slices.get(d).getDeletedGoals()));
		Map<String, Map<String, JsonObject>> copies = new LinkedHashMap<>();
		for (String device : devices)
		{
			for (JsonElement e : goals.getOrDefault(device, new JsonArray()))
			{
				String id = Trees.getString(e.getAsJsonObject(), "id");
				if (id != null && !deleted.contains(id))
				{
					copies.computeIfAbsent(id, k -> new LinkedHashMap<>()).put(device, e.getAsJsonObject());
				}
			}
		}

		List<JsonObject> out = new ArrayList<>();
		copies.forEach((id, byDevice) ->
		{
			JsonObject g = new JsonObject();
			JsonObject first = byDevice.values().iterator().next();
			Trees.copy(first, g, SAME);
			Trees.copy(first, g, DONE);
			Trees.copy(byDevice.get(newest(byDevice, slices, clock(id, "spec"))), g, SPEC);
			Trees.copy(byDevice.get(latestPlan(byDevice, slices, id)), g, PLAN);

			String doneBy = null;
			long done = 0;
			boolean affordable = false;
			for (Map.Entry<String, JsonObject> e : byDevice.entrySet())
			{
				long at = Trees.getLong(e.getValue(), "completedAt");
				if (at > 0 && (done == 0 || at < done))
				{
					done = at;
					doneBy = e.getKey();
				}
				affordable |= Trees.getBoolean(e.getValue(), "affordable");
			}
			if (doneBy != null)
			{
				Trees.copy(byDevice.get(doneBy), g, DONE);
			}
			g.addProperty("affordable", affordable);
			for (String key : SUM)
			{
				long total = 0;
				for (JsonObject copy : byDevice.values())
				{
					total += Trees.getLong(copy, key);
				}
				g.addProperty(key, total);
			}

			if (g.has("items") && g.get("items").isJsonArray())
			{
				for (JsonElement item : g.getAsJsonArray("items"))
				{
					itemState(id, item.getAsJsonObject(), byDevice, slices);
				}
			}
			out.add(g);
		});
		out.sort(Comparator.comparingLong((JsonObject g) -> Trees.getLong(g, "createdAt"))
			.thenComparing(g -> Trees.getString(g, "id")));
		JsonArray array = new JsonArray();
		out.forEach(array::add);
		return array;
	}

	static JsonArray reconcile(JsonArray viewGoals, JsonArray baseGoals, JsonArray ownGoals, ProfileSlice next, Hlc hlc)
	{
		Map<String, JsonObject> view = byId(viewGoals);
		Map<String, JsonObject> base = byId(baseGoals);
		Map<String, JsonObject> own = byId(ownGoals);
		JsonArray out = new JsonArray();
		view.forEach((id, vg) ->
		{
			JsonObject bg = base.get(id);
			if (bg == null)
			{
				JsonObject ng = vg.deepCopy();
				next.getClocks().put(clock(id, "spec"), hlc.next());
				next.getClocks().put(clock(id, "plan"), hlc.next());
				for (JsonElement item : items(vg))
				{
					next.getClocks().put(clock(id, "item." + itemKey(item.getAsJsonObject())), hlc.next());
				}
				out.add(ng);
				return;
			}

			JsonObject og = own.get(id);
			JsonObject ng;
			if (og != null)
			{
				ng = og.deepCopy();
			}
			else
			{
				ng = vg.deepCopy();
				SUM.forEach(k -> ng.addProperty(k, 0));
			}
			if (!Objects.equals(spec(vg), spec(bg)))
			{
				Trees.copy(vg, ng, SPEC);
				next.getClocks().put(clock(id, "spec"), hlc.next());
			}
			if (!Objects.equals(Trees.only(vg, PLAN), Trees.only(bg, PLAN)))
			{
				Trees.copy(vg, ng, PLAN);
				next.getClocks().put(clock(id, "plan"), hlc.next());
			}
			Map<String, JsonObject> baseItems = itemsByKey(bg);
			for (JsonElement e : items(vg))
			{
				JsonObject item = e.getAsJsonObject();
				String key = itemKey(item);
				JsonObject was = baseItems.get(key);
				if (was == null || !Trees.only(item, ITEM_STATE).equals(Trees.only(was, ITEM_STATE)))
				{
					JsonObject mine = itemsByKey(ng).get(key);
					if (mine == null)
					{
						mine = item.deepCopy();
						if (!ng.has("items") || !ng.get("items").isJsonArray())
						{
							ng.add("items", new JsonArray());
						}
						ng.getAsJsonArray("items").add(mine);
					}
					Trees.copy(item, mine, ITEM_STATE);
					next.getClocks().put(clock(id, "item." + key), hlc.next());
				}
			}
			if (Trees.getLong(vg, "completedAt") != Trees.getLong(bg, "completedAt"))
			{
				Trees.copy(vg, ng, DONE);
			}
			if (Trees.getBoolean(vg, "affordable") && !Trees.getBoolean(bg, "affordable"))
			{
				ng.addProperty("affordable", true);
			}
			for (String key : SUM)
			{
				ng.addProperty(key, Trees.getLong(ng, key) + Trees.getLong(vg, key) - Trees.getLong(bg, key));
			}
			out.add(ng);
		});
		base.keySet().forEach(id ->
		{
			if (!view.containsKey(id))
			{
				next.getDeletedGoals().add(id);
			}
		});
		return out;
	}

	private static void itemState(String goalId, JsonObject item, Map<String, JsonObject> byDevice, Map<String, ProfileSlice> slices)
	{
		String key = itemKey(item);
		String clockKey = clock(goalId, "item." + key);
		JsonObject best = null;
		long bestClock = -1;
		for (Map.Entry<String, JsonObject> e : byDevice.entrySet())
		{
			JsonObject theirs = itemsByKey(e.getValue()).get(key);
			if (theirs == null)
			{
				continue;
			}
			long c = slices.get(e.getKey()).getClocks().getOrDefault(clockKey, 0L);
			if (best == null || c > bestClock || (c == bestClock && Trees.getLong(theirs, "obtainedAt") > 0 && Trees.getLong(best, "obtainedAt") == 0))
			{
				best = theirs;
				bestClock = c;
			}
		}
		if (best != null)
		{
			Trees.copy(best, item, ITEM_STATE);
		}
	}

	private static String newest(Map<String, JsonObject> byDevice, Map<String, ProfileSlice> slices, String clockKey)
	{
		String best = null;
		long bestClock = -1;
		for (String device : byDevice.keySet())
		{
			long c = slices.get(device).getClocks().getOrDefault(clockKey, 0L);
			if (c > bestClock)
			{
				best = device;
				bestClock = c;
			}
		}
		return best;
	}

	private static String latestPlan(Map<String, JsonObject> byDevice, Map<String, ProfileSlice> slices, String id)
	{
		String best = null;
		String bestWeek = null;
		long bestClock = -1;
		for (Map.Entry<String, JsonObject> e : byDevice.entrySet())
		{
			String week = Trees.getString(e.getValue(), "weekStart");
			long c = slices.get(e.getKey()).getClocks().getOrDefault(clock(id, "plan"), 0L);
			int cmp = best == null ? 1 : compare(week, bestWeek);
			if (cmp > 0 || (cmp == 0 && c > bestClock))
			{
				best = e.getKey();
				bestWeek = week;
				bestClock = c;
			}
		}
		return best;
	}

	private static int compare(String a, String b)
	{
		if (a == null)
		{
			return b == null ? 0 : -1;
		}
		return b == null ? 1 : a.compareTo(b);
	}

	private static JsonObject spec(JsonObject goal)
	{
		JsonObject spec = Trees.only(goal, SPEC);
		if (spec.has("items") && spec.get("items").isJsonArray())
		{
			for (JsonElement item : spec.getAsJsonArray("items"))
			{
				ITEM_STATE.forEach(item.getAsJsonObject()::remove);
			}
		}
		return spec;
	}

	static String clock(String goalId, String part)
	{
		return "goal." + goalId + "." + part;
	}

	private static JsonArray items(JsonObject goal)
	{
		JsonElement items = goal.get("items");
		return items != null && items.isJsonArray() ? items.getAsJsonArray() : new JsonArray();
	}

	private static Map<String, JsonObject> itemsByKey(JsonObject goal)
	{
		Map<String, JsonObject> out = new LinkedHashMap<>();
		for (JsonElement e : items(goal))
		{
			out.putIfAbsent(itemKey(e.getAsJsonObject()), e.getAsJsonObject());
		}
		return out;
	}

	static String itemKey(JsonObject item)
	{
		long id = Trees.getLong(item, "id");
		if (id > 0)
		{
			return "id:" + id;
		}
		String name = Trees.getString(item, "name");
		return "name:" + (name == null ? "" : name.toLowerCase(Locale.ENGLISH));
	}

	private static Map<String, JsonObject> byId(JsonArray goals)
	{
		Map<String, JsonObject> out = new LinkedHashMap<>();
		if (goals != null)
		{
			for (JsonElement e : goals)
			{
				String id = Trees.getString(e.getAsJsonObject(), "id");
				if (id != null)
				{
					out.put(id, e.getAsJsonObject());
				}
			}
		}
		return out;
	}

	private static Set<String> keys(String... keys)
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(keys)));
	}
}

package com.runejourney.sync;

import java.util.function.LongSupplier;

public final class Hlc
{
	private final LongSupplier wallClock;
	private final boolean frozen;
	private long last;

	public Hlc(long last)
	{
		this(last, System::currentTimeMillis);
	}

	Hlc(long last, LongSupplier wallClock)
	{
		this(last, wallClock, false);
	}

	private Hlc(long last, LongSupplier wallClock, boolean frozen)
	{
		this.last = last;
		this.wallClock = wallClock;
		this.frozen = frozen;
	}

	public static Hlc zero()
	{
		return new Hlc(0, () -> 0, true);
	}

	public synchronized long next()
	{
		if (frozen)
		{
			return 0;
		}
		last = Math.max(wallClock.getAsLong(), last + 1);
		return last;
	}

	public synchronized void observe(long clock)
	{
		if (!frozen)
		{
			last = Math.max(last, clock);
		}
	}

	public synchronized long last()
	{
		return last;
	}
}

package com.runejourney.sync;

import com.google.gson.*;
import com.runejourney.model.*;
import java.util.*;

public final class ProfileJoin
{
	enum Rule
	{
		LOCAL,
		MAX,
		EARLIEST_SET,
		ANY,
		MAP_MAX,
		MAP_ADD,
		NEWEST,
		MAP_NEWEST,
		LATEST_DATE,
		LONGEST_SESSION,
		GOALS
	}

	static final Map<String, Rule> RULES = new LinkedHashMap<>();

	static
	{
		RULES.put("playerName", Rule.LOCAL);
		RULES.put("createdAt", Rule.EARLIEST_SET);
		RULES.put("lastXp", Rule.MAP_MAX);
		RULES.put("lastXpAt", Rule.MAX);
		RULES.put("killCounts", Rule.MAP_MAX);
		RULES.put("savedMethods", Rule.MAP_NEWEST);
		RULES.put("detectedMethods", Rule.MAP_NEWEST);
		RULES.put("dismissedRates", Rule.MAP_NEWEST);
		RULES.put("killTimes", Rule.MAP_ADD);
		RULES.put("clueCounts", Rule.MAP_MAX);
		RULES.put("combatAchievementPoints", Rule.NEWEST);
		RULES.put("combatTasks", Rule.MAX);
		RULES.put("combatTasksFromGame", Rule.ANY);
		RULES.put("questPoints", Rule.MAX);
		RULES.put("collectionLogSlots", Rule.MAX);
		RULES.put("collectionLogTotal", Rule.MAX);
		RULES.put("bankCash", Rule.NEWEST);
		RULES.put("bankCashKnown", Rule.ANY);
		RULES.put("inventoryCash", Rule.NEWEST);
		RULES.put("geSlots", Rule.NEWEST);
		RULES.put("holdings", Rule.MAP_NEWEST);
		RULES.put("wealthParts", Rule.MAP_NEWEST);
		RULES.put("bankValueKnown", Rule.ANY);
		RULES.put("bankValue", Rule.LOCAL);
		RULES.put("inventoryValue", Rule.LOCAL);
		RULES.put("equipmentValue", Rule.LOCAL);
		RULES.put("bestWealth", Rule.MAX);
		RULES.put("collectionLog", Rule.MAP_NEWEST);
		RULES.put("collectionLogTabs", Rule.NEWEST);
		RULES.put("collectionLogSyncedAt", Rule.MAX);
		RULES.put("overlayGoalId", Rule.NEWEST);
		RULES.put("longestSessionMillis", Rule.LONGEST_SESSION);
		RULES.put("longestSessionDate", Rule.LONGEST_SESSION);
		RULES.put("bestPlayStreak", Rule.MAX);
		RULES.put("wrappedSeen", Rule.LATEST_DATE);
		RULES.put("wrappedNotified", Rule.LATEST_DATE);
		RULES.put("goals", Rule.GOALS);
		RULES.put("session", Rule.NEWEST);
		RULES.put("bestXpDay", Rule.MAX);
		RULES.put("bestLootDay", Rule.MAX);
		RULES.put("preferredMethods", Rule.MAP_NEWEST);
		RULES.put("sync", Rule.LOCAL);
	}

	private ProfileJoin()
	{
	}

	public static ProfileData combine(Gson gson, ProfileData local, Map<String, ProfileSlice> slices)
	{
		List<String> devices = new ArrayList<>();
		Map<String, JsonObject> trees = new HashMap<>();
		slices.forEach((device, slice) ->
		{
			if (slice != null && slice.getProfile() != null)
			{
				devices.add(device);
				trees.put(device, gson.toJsonTree(slice.getProfile()).getAsJsonObject());
			}
		});
		Collections.sort(devices);
		JsonObject mine = local == null ? new JsonObject() : gson.toJsonTree(local).getAsJsonObject();

		JsonObject out = new JsonObject();
		RULES.forEach((field, rule) ->
		{
			switch (rule)
			{
				case LOCAL:
					Trees.copy(mine, out, Collections.singleton(field));
					break;
				case MAX:
					maxOf(devices, trees, field).ifPresent(v -> out.addProperty(field, v));
					break;
				case EARLIEST_SET:
					earliestSet(devices, trees, field).ifPresent(v -> out.addProperty(field, v));
					break;
				case ANY:
					out.addProperty(field, devices.stream().anyMatch(d -> Trees.getBoolean(trees.get(d), field)));
					break;
				case MAP_MAX:
					out.add(field, mapMax(devices, trees, field));
					break;
				case MAP_ADD:
				{
					JsonObject sum = new JsonObject();
					devices.forEach(d -> Trees.add(sum, Trees.object(trees.get(d), field), 1));
					Trees.prune(sum);
					out.add(field, sum);
					break;
				}
				case NEWEST:
				{
					JsonElement v = newest(devices, trees, slices, field, field);
					if (Trees.present(v))
					{
						out.add(field, v.deepCopy());
					}
					break;
				}
				case MAP_NEWEST:
					out.add(field, mapNewest(devices, trees, slices, field));
					break;
				case LATEST_DATE:
				{
					String latest = null;
					for (String d : devices)
					{
						String v = Trees.getString(trees.get(d), field);
						if (v != null && (latest == null || v.compareTo(latest) > 0))
						{
							latest = v;
						}
					}
					if (latest != null)
					{
						out.addProperty(field, latest);
					}
					break;
				}
				case LONGEST_SESSION:
				{
					String best = null;
					for (String d : devices)
					{
						if (best == null || Trees.getLong(trees.get(d), "longestSessionMillis") > Trees.getLong(trees.get(best), "longestSessionMillis"))
						{
							best = d;
						}
					}
					if (best != null)
					{
						Trees.copy(trees.get(best), out, Collections.singleton(field));
					}
					break;
				}
				case GOALS:
				{
					Map<String, JsonArray> goals = new HashMap<>();
					devices.forEach(d -> goals.put(d, array(trees.get(d), field)));
					out.add(field, GoalJoin.combine(devices, goals, slices));
					break;
				}
			}
		});
		return gson.fromJson(out, ProfileData.class);
	}

	public static ProfileSlice reconcile(Gson gson, ProfileData view, String me, Map<String, ProfileSlice> slices, Hlc hlc)
	{
		ProfileSlice own = slices.get(me);
		Map<String, JsonObject> remotes = new HashMap<>();
		slices.forEach((device, slice) ->
		{
			if (!device.equals(me) && slice != null && slice.getProfile() != null)
			{
				remotes.put(device, gson.toJsonTree(slice.getProfile()).getAsJsonObject());
			}
		});
		JsonObject v = gson.toJsonTree(view).getAsJsonObject();
		JsonObject base = gson.toJsonTree(combine(gson, view, slices)).getAsJsonObject();
		JsonObject o = own != null && own.getProfile() != null ? gson.toJsonTree(own.getProfile()).getAsJsonObject() : new JsonObject();

		ProfileSlice next = new ProfileSlice();
		if (own != null)
		{
			next.getClocks().putAll(own.getClocks());
			next.getDeletedGoals().addAll(own.getDeletedGoals());
		}
		JsonObject out = new JsonObject();
		RULES.forEach((field, rule) ->
		{
			switch (rule)
			{
				case LOCAL:
					break;
				case MAX:
				case EARLIEST_SET:
				case ANY:
				case MAP_MAX:
				case LATEST_DATE:
				case LONGEST_SESSION:
					Trees.copy(v, out, Collections.singleton(field));
					break;
				case MAP_ADD:
				{
					JsonObject m = Trees.object(v, field).deepCopy();
					remotes.values().forEach(r -> Trees.add(m, Trees.object(r, field), -1));
					Trees.prune(m);
					out.add(field, m);
					break;
				}
				case NEWEST:
					if (!Objects.equals(v.get(field), base.get(field)))
					{
						Trees.copy(v, out, Collections.singleton(field));
						next.getClocks().put(field, hlc.next());
					}
					else
					{
						Trees.copy(o, out, Collections.singleton(field));
					}
					break;
				case MAP_NEWEST:
				{
					JsonObject vm = Trees.object(v, field);
					JsonObject bm = Trees.object(base, field);
					JsonObject om = Trees.object(o, field).deepCopy();
					Set<String> keys = new TreeSet<>(vm.keySet());
					keys.addAll(bm.keySet());
					for (String key : keys)
					{
						if (!Objects.equals(vm.get(key), bm.get(key)))
						{
							if (vm.has(key))
							{
								om.add(key, vm.get(key).deepCopy());
							}
							else
							{
								om.remove(key);
							}
							next.getClocks().put(field + "." + key, hlc.next());
						}
					}
					out.add(field, om);
					break;
				}
				case GOALS:
					out.add(field, GoalJoin.reconcile(array(v, field), array(base, field), array(o, field), next, hlc));
					break;
			}
		});
		next.setProfile(gson.fromJson(out, ProfileData.class));
		return next;
	}

	public static boolean matches(Gson gson, ProfileData view, Map<String, ProfileSlice> slices)
	{
		JsonObject v = gson.toJsonTree(view).getAsJsonObject();
		JsonObject c = gson.toJsonTree(combine(gson, view, slices)).getAsJsonObject();
		for (Map.Entry<String, Rule> e : RULES.entrySet())
		{
			if (e.getValue() == Rule.LOCAL)
			{
				continue;
			}
			JsonElement a = v.get(e.getKey());
			JsonElement b = c.get(e.getKey());
			if (e.getValue() == Rule.GOALS)
			{
				a = byIdObject(a);
				b = byIdObject(b);
			}
			else if (e.getValue() == Rule.MAP_ADD)
			{
				a = pruned(a);
				b = pruned(b);
			}
			if (!Objects.equals(emptyToNull(a), emptyToNull(b)))
			{
				return false;
			}
		}
		return true;
	}

	public static long latestClock(ProfileSlice slice)
	{
		long latest = 0;
		for (long c : slice.getClocks().values())
		{
			latest = Math.max(latest, c);
		}
		return latest;
	}

	private static JsonElement emptyToNull(JsonElement e)
	{
		if (e == null || e.isJsonNull() || (e.isJsonObject() && e.getAsJsonObject().size() == 0)
			|| (e.isJsonArray() && e.getAsJsonArray().size() == 0))
		{
			return null;
		}
		return e;
	}

	private static JsonElement pruned(JsonElement e)
	{
		if (e == null || !e.isJsonObject())
		{
			return e;
		}
		JsonObject copy = e.getAsJsonObject().deepCopy();
		Trees.prune(copy);
		return copy;
	}

	private static JsonElement byIdObject(JsonElement goals)
	{
		JsonObject out = new JsonObject();
		if (goals != null && goals.isJsonArray())
		{
			for (JsonElement g : goals.getAsJsonArray())
			{
				out.add(String.valueOf(Trees.getString(g.getAsJsonObject(), "id")), g);
			}
		}
		return out;
	}

	private static JsonArray array(JsonObject o, String field)
	{
		JsonElement e = o.get(field);
		return e != null && e.isJsonArray() ? e.getAsJsonArray() : new JsonArray();
	}

	private static OptionalLong maxOf(List<String> devices, Map<String, JsonObject> trees, String field)
	{
		Long best = null;
		for (String d : devices)
		{
			JsonElement e = trees.get(d).get(field);
			if (Trees.present(e))
			{
				best = best == null ? e.getAsLong() : Math.max(best, e.getAsLong());
			}
		}
		return best == null ? OptionalLong.empty() : OptionalLong.of(best);
	}

	private static OptionalLong earliestSet(List<String> devices, Map<String, JsonObject> trees, String field)
	{
		long best = 0;
		for (String d : devices)
		{
			long v = Trees.getLong(trees.get(d), field);
			if (v > 0 && (best == 0 || v < best))
			{
				best = v;
			}
		}
		return best == 0 ? OptionalLong.empty() : OptionalLong.of(best);
	}

	private static JsonObject mapMax(List<String> devices, Map<String, JsonObject> trees, String field)
	{
		JsonObject out = new JsonObject();
		for (String d : devices)
		{
			for (Map.Entry<String, JsonElement> e : Trees.object(trees.get(d), field).entrySet())
			{
				if (!e.getValue().isJsonPrimitive())
				{
					continue;
				}
				long v = e.getValue().getAsLong();
				if (!out.has(e.getKey()) || out.get(e.getKey()).getAsLong() < v)
				{
					out.addProperty(e.getKey(), v);
				}
			}
		}
		return out;
	}

	private static JsonElement newest(List<String> devices, Map<String, JsonObject> trees, Map<String, ProfileSlice> slices,
		String clockKey, String field)
	{
		JsonElement best = null;
		long bestClock = -1;
		for (String d : devices)
		{
			long c = slices.get(d).getClocks().getOrDefault(clockKey, 0L);
			JsonElement v = trees.get(d).get(field);
			if (c > bestClock || (c == bestClock && Trees.present(v) && !Trees.present(best)))
			{
				best = v;
				bestClock = c;
			}
		}
		return best;
	}

	private static JsonObject mapNewest(List<String> devices, Map<String, JsonObject> trees, Map<String, ProfileSlice> slices, String field)
	{
		Set<String> keys = new TreeSet<>();
		String prefix = field + ".";
		for (String d : devices)
		{
			keys.addAll(Trees.object(trees.get(d), field).keySet());
			for (String clock : slices.get(d).getClocks().keySet())
			{
				if (clock.startsWith(prefix))
				{
					keys.add(clock.substring(prefix.length()));
				}
			}
		}
		JsonObject out = new JsonObject();
		for (String key : keys)
		{
			JsonElement best = null;
			long bestClock = -1;
			for (String d : devices)
			{
				long c = slices.get(d).getClocks().getOrDefault(prefix + key, 0L);
				JsonElement v = Trees.object(trees.get(d), field).get(key);
				if (c > bestClock || (c == bestClock && Trees.present(v) && !Trees.present(best)))
				{
					best = v;
					bestClock = c;
				}
			}
			if (Trees.present(best))
			{
				out.add(key, best.deepCopy());
			}
		}
		return out;
	}
}

package com.runejourney.sync;

import com.google.gson.*;
import com.runejourney.model.*;
import java.util.*;

public final class Trees
{
	private Trees()
	{
	}

	public static Gson withoutSync(Gson gson)
	{
		return gson.newBuilder().addSerializationExclusionStrategy(new ExclusionStrategy()
		{
			@Override
			public boolean shouldSkipField(FieldAttributes f)
			{
				return "sync".equals(f.getName())
					&& (f.getDeclaringClass() == DayRecord.class || f.getDeclaringClass() == ProfileData.class);
			}

			@Override
			public boolean shouldSkipClass(Class<?> clazz)
			{
				return false;
			}
		}).create();
	}

	static void add(JsonObject into, JsonObject from, int sign)
	{
		for (Map.Entry<String, JsonElement> e : from.entrySet())
		{
			JsonElement value = e.getValue();
			JsonElement current = into.get(e.getKey());
			if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber())
			{
				long before = current != null && current.isJsonPrimitive() && current.getAsJsonPrimitive().isNumber() ? current.getAsLong() : 0;
				into.addProperty(e.getKey(), before + sign * value.getAsLong());
			}
			else if (value.isJsonObject())
			{
				JsonObject child = current != null && current.isJsonObject() ? current.getAsJsonObject() : new JsonObject();
				add(child, value.getAsJsonObject(), sign);
				into.add(e.getKey(), child);
			}
		}
	}

	static void prune(JsonObject o)
	{
		List<String> empty = new ArrayList<>();
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			JsonElement value = e.getValue();
			if (value.isJsonObject())
			{
				prune(value.getAsJsonObject());
				if (value.getAsJsonObject().size() == 0)
				{
					empty.add(e.getKey());
				}
			}
			else if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber() && value.getAsLong() == 0)
			{
				empty.add(e.getKey());
			}
		}
		empty.forEach(o::remove);
	}

	static long getLong(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber() ? e.getAsLong() : 0;
	}

	static boolean getBoolean(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() && e.getAsBoolean();
	}

	static String getString(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}

	static JsonObject object(JsonObject o, String key)
	{
		JsonElement e = o == null ? null : o.get(key);
		return e != null && e.isJsonObject() ? e.getAsJsonObject() : new JsonObject();
	}

	static void copy(JsonObject from, JsonObject to, Collection<String> keys)
	{
		for (String key : keys)
		{
			JsonElement value = from.get(key);
			if (value == null || value.isJsonNull())
			{
				to.remove(key);
			}
			else
			{
				to.add(key, value.deepCopy());
			}
		}
	}

	static JsonObject only(JsonObject from, Collection<String> keys)
	{
		JsonObject out = new JsonObject();
		copy(from, out, keys);
		return out;
	}

	static boolean present(JsonElement e)
	{
		return e != null && !e.isJsonNull();
	}
}

package com.runejourney.sync;

import com.runejourney.planner.Skills;
import java.util.*;

public final class XpRanges
{
	private XpRanges()
	{
	}

	public static List<long[]> normalize(Collection<long[]> ranges)
	{
		List<long[]> sorted = new ArrayList<>();
		for (long[] r : ranges)
		{
			if (r != null && r.length == 2 && r[1] > r[0])
			{
				sorted.add(new long[]{r[0], r[1]});
			}
		}
		sorted.sort((a, b) -> Long.compare(a[0], b[0]));
		List<long[]> out = new ArrayList<>();
		for (long[] r : sorted)
		{
			long[] last = out.isEmpty() ? null : out.get(out.size() - 1);
			if (last != null && r[0] <= last[1])
			{
				last[1] = Math.max(last[1], r[1]);
			}
			else
			{
				out.add(r);
			}
		}
		return out;
	}

	public static List<long[]> union(Collection<long[]> a, Collection<long[]> b)
	{
		List<long[]> all = new ArrayList<>(a);
		all.addAll(b);
		return normalize(all);
	}

	public static List<long[]> subtract(Collection<long[]> a, Collection<long[]> b)
	{
		List<long[]> out = new ArrayList<>();
		List<long[]> cut = normalize(b);
		for (long[] r : normalize(a))
		{
			long from = r[0];
			for (long[] c : cut)
			{
				if (c[1] <= from || c[0] >= r[1])
				{
					continue;
				}
				if (c[0] > from)
				{
					out.add(new long[]{from, c[0]});
				}
				from = Math.max(from, c[1]);
				if (from >= r[1])
				{
					break;
				}
			}
			if (from < r[1])
			{
				out.add(new long[]{from, r[1]});
			}
		}
		return out;
	}

	public static long length(Collection<long[]> ranges)
	{
		long total = 0;
		for (long[] r : ranges)
		{
			total += Math.max(0, r[1] - r[0]);
		}
		return total;
	}

	public static int levels(Collection<long[]> ranges)
	{
		int total = 0;
		for (long[] r : ranges)
		{
			total += Math.max(0, Skills.level(r[1]) - Skills.level(r[0]));
		}
		return total;
	}

	public static Map<String, List<long[]>> union(Map<String, List<long[]>> a, Map<String, List<long[]>> b)
	{
		Map<String, List<long[]>> out = new HashMap<>();
		Set<String> skills = new HashSet<>(a.keySet());
		skills.addAll(b.keySet());
		for (String skill : skills)
		{
			List<long[]> joined = union(orEmpty(a.get(skill)), orEmpty(b.get(skill)));
			if (!joined.isEmpty())
			{
				out.put(skill, joined);
			}
		}
		return out;
	}

	public static Map<String, List<long[]>> subtract(Map<String, List<long[]>> a, Map<String, List<long[]>> b)
	{
		Map<String, List<long[]>> out = new HashMap<>();
		a.forEach((skill, ranges) ->
		{
			List<long[]> left = subtract(ranges, orEmpty(b.get(skill)));
			if (!left.isEmpty())
			{
				out.put(skill, left);
			}
		});
		return out;
	}

	public static Map<String, List<long[]>> normalize(Map<String, List<long[]>> ranges)
	{
		return union(ranges, new HashMap<>());
	}

	public static boolean same(Map<String, List<long[]>> a, Map<String, List<long[]>> b)
	{
		Map<String, List<long[]>> x = normalize(a);
		Map<String, List<long[]>> y = normalize(b);
		if (!x.keySet().equals(y.keySet()))
		{
			return false;
		}
		for (Map.Entry<String, List<long[]>> e : x.entrySet())
		{
			List<long[]> other = y.get(e.getKey());
			if (other.size() != e.getValue().size())
			{
				return false;
			}
			for (int i = 0; i < other.size(); i++)
			{
				if (other.get(i)[0] != e.getValue().get(i)[0] || other.get(i)[1] != e.getValue().get(i)[1])
				{
					return false;
				}
			}
		}
		return true;
	}

	private static List<long[]> orEmpty(List<long[]> ranges)
	{
		return ranges == null ? new ArrayList<>() : ranges;
	}
}

