		this.maxRows = maxRows;
		setOpaque(true);
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int i = rowAt(e.getY());
				if (i != hover)
				{
					hover = i;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mouseClicked(MouseEvent e)
			{
				int i = rowAt(e.getY());
				if (onClick != null && i >= 0)
				{
					onClick.accept(entries.get(i));
				}
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	void setData(List<Analytics.Entry> entries, Unit unit, Color color)
	{
		this.entries = entries;
		this.unit = unit;
		this.color = color;
		hover = -1;
		revalidate();
		repaint();
	}

	void setOnClick(Consumer<Analytics.Entry> onClick)
	{
		this.onClick = onClick;
		setCursor(onClick == null ? Cursor.getDefaultCursor() : Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	void setIcons(Function<String, Icon> icons)
	{
		this.icons = icons;
	}

	void setLabels(Function<String, String> labels)
	{
		this.labels = labels;
	}

	void setEmptyText(String emptyText)
	{
		this.emptyText = emptyText;
	}

	private int rows()
	{
		return Math.min(maxRows, entries.size());
	}

	private int rowAt(int y)
	{
		int i = (y - 4) / ROW;
		return i >= 0 && i < rows() ? i : -1;
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(300, Math.max(ROW + 8, rows() * ROW + 8));
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		Graphics2D g = (Graphics2D) g0.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(getBackground());
		g.fillRect(0, 0, getWidth(), getHeight());
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();

		int rows = rows();
		if (rows == 0)
		{
			g.setColor(Ui.MUTED);
			g.drawString(emptyText, 8, 4 + fm.getAscent() + 3);
			g.dispose();
			return;
		}

		double max = 0;
		for (int i = 0; i < rows; i++)
		{
			max = Math.max(max, entries.get(i).getValue());
		}
		int valueW = 80;
		int barSpace = Math.max(10, getWidth() - LABEL_W - valueW - 12);
		for (int i = 0; i < rows; i++)
		{
			Analytics.Entry e = entries.get(i);
			int y = 4 + i * ROW;
			if (i == hover)
			{
				g.setColor(ColorScheme.DARKER_GRAY_HOVER_COLOR);
				g.fillRect(0, y, getWidth(), ROW);
			}
			int textY = y + (ROW + fm.getAscent()) / 2 - 2;
			int lx = 6;
			Icon icon = icons.apply(e.getKey());
			if (icon != null)
			{
				icon.paintIcon(this, g, lx, y + (ROW - icon.getIconHeight()) / 2);
				lx += icon.getIconWidth() + 5;
			}
			g.setColor(Color.WHITE);
			String label = labels.apply(e.getLabel());
			while (fm.stringWidth(label) > LABEL_W - lx - 6 && label.length() > 3)
			{
				label = label.substring(0, label.length() - 2);
			}
			g.drawString(label, lx, textY);

			int w = max <= 0 ? 0 : (int) Math.max(2, e.getValue() / max * barSpace);
			g.setColor(i == hover ? color.brighter() : color);
			g.fillRoundRect(LABEL_W, y + 5, w, ROW - 10, 4, 4);
			g.setColor(Ui.MUTED);
			g.drawString(unit.format(e.getValue()), LABEL_W + w + 6, textY);
		}
		g.dispose();
	}
}

package com.runejourney.ui;

import com.runejourney.RuneJourneyConfig;
import com.runejourney.cloud.*;
import java.awt.*;
import javax.inject.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

class CloudSection
{
	private static final String WARNING = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	private final SyncManager sync;
	private final ConfigManager configManager;
	private final boolean developerMode;

	final JLabel link;
	final JPanel prompts = Ui.stack(4);
	final JPanel card = Ui.stack(4);

	private CloudStatus shown;
	private long shownAt;
	private boolean open;
	private final JPasswordField keyField = new JPasswordField();
	private final JTextField serverField = new JTextField();

	@Inject
	CloudSection(SyncManager sync, ConfigManager configManager, RuneJourneyConfig config, @Named("developerMode") boolean developerMode)
	{
		this.sync = sync;
		this.configManager = configManager;
		this.developerMode = developerMode;
		this.link = Ui.link("", this::toggle);
		link.setBorder(new EmptyBorder(2, 0, 0, 0));
		prompts.setBorder(new EmptyBorder(0, 0, 6, 0));
		card.setBorder(new EmptyBorder(0, 0, 6, 0));
		card.setVisible(false);
		Ui.styled(keyField);
		Ui.styled(serverField);
		serverField.setText(config.cloudServer());
	}

	private void toggle()
	{
		open = !open;
		shown = null;
		refresh();
	}

	void refresh()
	{
		CloudStatus s = sync.status();
		if (s.equals(shown) && (s.getLastSync() == 0 || System.currentTimeMillis() - shownAt < 30_000))
		{
			return;
		}
		shown = s;
		shownAt = System.currentTimeMillis();

		link.setText(summary(s));
		link.setToolTipText(open ? "Hide cloud sync" : "Cloud sync: back up your journey and use it on any PC");

		prompts.removeAll();
		addPrompts(s);
		prompts.setVisible(prompts.getComponentCount() > 0);
		prompts.revalidate();
		prompts.repaint();

		card.removeAll();
		if (open)
		{
			card.add(cloudCard(s));
		}
		card.setVisible(card.getComponentCount() > 0);
		card.revalidate();
		card.repaint();
	}

	private static String summary(CloudStatus s)
	{
		switch (s.getConnection())
		{
			case OFF:
				return "Cloud sync: off";
			case NOT_CONNECTED:
				return "Cloud sync: connect";
			case CONNECTING:
				return "Cloud sync: connecting...";
			case KEY_REJECTED:
				return "Cloud sync: paste a new key";
			default:
				break;
		}
		if (s.isUpdateNeeded())
		{
			return "Cloud sync: update needed";
		}
		if (s.isSyncing())
		{
			return "Cloud sync: syncing...";
		}
		if (s.getProblem() != null)
		{
			return "Cloud sync: will retry";
		}
		if (s.isLinked())
		{
			return s.getLastSync() > 0 ? "Cloud sync: synced " + ago(s.getLastSync()) : "Cloud sync: on";
		}
		if (Boolean.FALSE.equals(s.getConsent()))
		{
			return "Cloud sync: not on this PC";
		}
		return "Cloud sync: connected";
	}

	private void addPrompts(CloudStatus s)
	{
		String account = s.getAccount() != null ? s.getAccount() : "This account";
		if (s.isReadOnly())
		{
			JPanel card = Ui.accentCard(Ui.WARN);
			card.add(Ui.title("Open in another window"));
			card.add(Ui.text(account + " is open in another RuneLite window, so this window isn't saving it. "
				+ "Log out there, then log in again here."));
			prompts.add(card);
			return;
		}
		if (s.getConnection() == CloudStatus.Connection.KEY_REJECTED)
		{
			JPanel card = Ui.accentCard(Ui.BAD);
			card.add(Ui.title("Cloud sync stopped"));
			card.add(Ui.text("This key no longer works. Your journey is still saved on this PC. Paste a new key to keep syncing."));
			card.add(buttons(Ui.button("Paste a new key", this::openCard)));
			prompts.add(card);
			return;
		}
		if (s.isUpdateNeeded() && s.getConnection() == CloudStatus.Connection.CONNECTED)
		{
			JPanel card = Ui.accentCard(Ui.WARN);
			card.add(Ui.title("Update RuneJourney"));
			card.add(Ui.text("A newer RuneJourney saved this account on another PC. Update RuneJourney to keep syncing."));
			prompts.add(card);
			return;
		}
		switch (s.getPrompt())
		{
			case CONSENT:
			{
				JPanel card = Ui.accentCard(Ui.GOLD);
				card.add(Ui.title("Save " + account + " to the cloud?"));
				card.add(Ui.text(s.isSavedElsewhere()
					? account + " is already saved in " + s.getUserName() + "'s cloud from another PC. Sync it on this PC too?"
					: "Back up " + account + "'s journey to " + s.getUserName() + "'s RuneJourney cloud, so you can use it on any PC."));
				card.add(buttons(Ui.button("Save", () -> sync.consent(true)), Ui.button("Not on this PC", () -> sync.consent(false))));
				prompts.add(card);
				break;
			}
			case CHOOSE:
			{
				JPanel card = Ui.accentCard(Ui.GOLD);
				card.add(Ui.title("Which journey?"));
				card.add(Ui.text(account + " already has a journey in the cloud, and this PC has its own. Use the cloud's "
					+ "(this PC's is backed up first), or combine both?"));
				card.add(Ui.muted("Combining can count XP gained while away twice, if both PCs found it."));
				card.add(buttons(Ui.button("Use the cloud's", () -> sync.choose(true)), Ui.button("Combine both", () -> sync.choose(false))));
				prompts.add(card);
				break;
			}
			default:
				break;
		}
	}

	private void openCard()
	{
		open = true;
		shown = null;
		refresh();
	}

	private JPanel cloudCard(CloudStatus s)
	{
		JPanel card = Ui.section("Cloud sync");
		switch (s.getConnection())
		{
			case OFF:
				card.add(Ui.text("Back up your journey and goals, and keep them in step on every PC you play on. "
					+ "Everything is encrypted before it leaves this PC."));
				card.add(buttons(Ui.button("Turn on cloud sync", this::turnOn)));
				break;
			case CONNECTING:
				card.add(Ui.text("Checking your key..."));
				break;
			case NOT_CONNECTED:
			case KEY_REJECTED:
				connectForm(card);
				break;
			case CONNECTED:
				connected(card, s);
				break;
		}
		if (s.getProblem() != null && s.getConnection() != CloudStatus.Connection.OFF)
		{
			card.add(Ui.label(s.getProblem(), FontManager.getRunescapeSmallFont(), Ui.WARN));
		}
		if (developerMode && s.getConnection() != CloudStatus.Connection.OFF)
		{
			devServer(card);
		}
		return card;
	}

	private void turnOn()
	{
		int ok = JOptionPane.showConfirmDialog(card, WARNING + ".\n\nTurn on cloud sync?", "RuneJourney",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
		if (ok == JOptionPane.OK_OPTION)
		{
			configManager.setConfiguration(RuneJourneyConfig.GROUP, "cloudSync", true);
		}
	}

	private void connectForm(JPanel card)
	{
		card.add(Ui.text("1. Sign in with Discord on the RuneJourney website and make a key for this PC. "
			+ "The key's name (e.g. Desktop) is how this PC shows on the website."));
		card.add(buttons(Ui.button("Get a key", this::openWebsite)));
		card.add(Ui.text("2. Paste the key here:"));
		card.add(keyField);
		card.add(buttons(Ui.button("Connect", () ->
		{
			String key = new String(keyField.getPassword()).trim();
			if (key.isEmpty())
			{
				JOptionPane.showMessageDialog(card, "Paste the key from the website first.", "RuneJourney", JOptionPane.WARNING_MESSAGE);
				return;
			}
			keyField.setText("");
			sync.connect(key);
		})));
	}

	private void connected(JPanel card, CloudStatus s)
	{
		card.add(Ui.stat("Connected as", s.getUserName() != null ? s.getUserName() : "you"));
		if (s.getDeviceName() != null)
		{
			card.add(Ui.stat("This PC", s.getDeviceName()));
		}

		if (s.getAccount() != null)
		{
			if (s.isLinked())
			{
				card.add(Ui.stat(s.getAccount(), s.isSyncing() ? "Syncing..."
					: s.getLastSync() > 0 ? "Synced " + ago(s.getLastSync()) : "Saved to the cloud", Ui.GOOD));
				if (s.getWaiting() > 0)
				{
					card.add(Ui.muted(s.getWaiting() + (s.getWaiting() == 1 ? " change" : " changes") + " waiting to upload."));
				}
				publicPage(card, s);
			}
			else if (Boolean.FALSE.equals(s.getConsent()))
			{
				card.add(Ui.row(Ui.small(s.getAccount() + " isn't saved from this PC.", Ui.MUTED), Ui.link("Save it", () -> sync.consent(true))));
			}
		}

		JPanel row = new JPanel(new GridLayout(1, 2, 4, 0));
		row.setOpaque(false);
		row.add(Ui.button("Sync now", sync::syncNow));
		row.add(Ui.button("Manage", this::openWebsite));
		card.add(row);
		card.add(buttons(Ui.button("Disconnect this PC", this::disconnect)));
		card.add(Ui.muted("Deleting cloud data and keys is done on the website, signed in with Discord."));
	}

	private void publicPage(JPanel card, CloudStatus s)
	{
		JLabel heading = Ui.small("Public page", Ui.GOLD);
		heading.setBorder(new EmptyBorder(6, 0, 0, 0));
		card.add(heading);
		if (s.isPublicBlocked())
		{
			card.add(Ui.label("This account's public page was taken down after a report.", FontManager.getRunescapeSmallFont(), Ui.WARN));
			return;
		}
		if (!s.isPublicEnabled())
		{
			card.add(Ui.muted("Share " + s.getAccount() + "'s journey on the RuneJourney website: your character, levels, kills, timeline and goals. "
				+ "It shows your RuneScape name."));
			card.add(buttons(Ui.button("Make public", () -> makePublic(s))));
			return;
		}
		String url = s.getPublicUrl();
		if (url != null)
		{
			JLabel link = Ui.link(shortUrl(url), () -> LinkBrowser.browse(url));
			link.setToolTipText(url);
			card.add(link);
		}
		else
		{
			card.add(Ui.muted("Publishing after the next sync..."));
		}
		if (s.getPublicCharacter() == CloudStatus.Character.WAITING)
		{
			card.add(Ui.muted("Stand still in game for a moment to put your character on the page."));
		}
		else if (s.getPublicCharacter() == CloudStatus.Character.SENDING)
		{
			card.add(Ui.muted("Sending your character..."));
		}
		JCheckBox search = Ui.styled(new JCheckBox("Show in the website's search", s.isPublicSearchable()));
		search.setOpaque(false);
		search.addActionListener(e -> sync.setPublic(null, search.isSelected()));
		card.add(search);
		if (s.getPublicProblem() != null)
		{
			card.add(Ui.label(s.getPublicProblem(), FontManager.getRunescapeSmallFont(), Ui.WARN));
		}
		JPanel row = new JPanel(new GridLayout(1, 2, 4, 0));
		row.setOpaque(false);
		row.add(Ui.button("Choose what it shows", this::openWebsite));
		row.add(Ui.button("Make private", () ->
		{
			int ok = JOptionPane.showConfirmDialog(card, "Make " + s.getAccount() + "'s journey private?\nIts public page is deleted.",
				"RuneJourney", JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
			if (ok == JOptionPane.OK_OPTION)
			{
				sync.setPublic(false, null);
			}
		}));
		card.add(row);
	}

	private void makePublic(CloudStatus s)
	{
		int ok = JOptionPane.showConfirmDialog(card, "Make " + s.getAccount() + "'s journey public?\n\n"
				+ "Anyone can see its page on the RuneJourney website, with your RuneScape name, your character\n"
				+ "in 3D, levels, kills, timeline, goals and records. Screenshots, notes, memories and net worth\n"
				+ "stay hidden unless you show them on the website. You can make it private again at any time.",
			"RuneJourney", JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
		if (ok == JOptionPane.OK_OPTION)
		{
			sync.setPublic(true, null);
		}
	}

	private static String shortUrl(String url)
	{
		return url.replaceFirst("^https?://", "");
	}

	private void disconnect()
	{
		int ok = JOptionPane.showConfirmDialog(card, "Disconnect this PC from your RuneJourney cloud?\n"
				+ "Your journey stays on this PC, and what's in the cloud stays there.",
			"RuneJourney", JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
		if (ok == JOptionPane.OK_OPTION)
		{
			sync.disconnect();
		}
	}

	private void devServer(JPanel card)
	{
		card.add(Ui.muted("Developer mode: cloud server address (leave blank for " + SyncManager.SERVER + ")"));
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.add(serverField, BorderLayout.CENTER);
		row.add(Ui.button("Use", () -> configManager.setConfiguration(RuneJourneyConfig.GROUP, "cloudServer", serverField.getText().trim())),
			BorderLayout.EAST);
		card.add(row);
	}

	private void openWebsite()
	{
		String server = sync.server();
		if (!server.isEmpty())
		{
			LinkBrowser.browse((server.endsWith("/") ? server : server + "/") + "cloud");
		}
	}

	private static JPanel buttons(JComponent... buttons)
	{
		JPanel row = new JPanel(new GridLayout(1, buttons.length, 4, 0));
		row.setOpaque(false);
		for (JComponent b : buttons)
		{
			row.add(b);
		}
		return row;
	}

	static String ago(long millis)
	{
		long minutes = (System.currentTimeMillis() - millis) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + " min ago";
		}
		long hours = minutes / 60;
		if (hours < 24)
		{
			return hours + (hours == 1 ? " hour ago" : " hours ago");
		}
		long days = hours / 24;
		return days + (days == 1 ? " day ago" : " days ago");
	}
}

package com.runejourney.ui;

import com.runejourney.service.*;
import java.awt.*;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.*;
import lombok.*;

class DiscoverTab extends RefreshableTab
{
	@Getter
	@RequiredArgsConstructor
	enum TimeAvailable
	{
		MIN_15("I've got 15 minutes", 15),
		MIN_30("I've got 30 minutes", 30),
		HOUR_1("I've got an hour", 60),
		HOUR_2("I've got a couple of hours", 120);

		private final String label;
		private final int minutes;

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final JourneyService service;
	private final Views views;
	private final JComboBox<TimeAvailable> timeBox = new JComboBox<>(TimeAvailable.values());
	private final JPanel body = Ui.stack(4);
	private int lastVersion = -1;
	private long lastRefresh;

	@Inject
	DiscoverTab(JourneyService service, Views views)
	{
		this.service = service;
		this.views = views;
		setLayout(new BorderLayout(0, 6));
		setOpaque(false);
		timeBox.setSelectedItem(TimeAvailable.MIN_30);
		Ui.styled(timeBox);
		timeBox.addActionListener(e -> refresh(true));
		add(timeBox, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	@Override
	void refresh(boolean force)
	{
		long now = System.currentTimeMillis();
		int version = service.getVersion();
		if (!force && (version == lastVersion || now - lastRefresh < 15_000))
		{
			return;
		}
		lastVersion = version;
		lastRefresh = now;

		Map<String, List<Suggestion>> sections = service.discover(((TimeAvailable) timeBox.getSelectedItem()).getMinutes());
		body.removeAll();
		for (Map.Entry<String, List<Suggestion>> section : sections.entrySet())
		{
			body.add(Ui.header(section.getKey()));
			if (section.getValue().isEmpty())
			{
				body.add(Ui.empty(emptyText(section.getKey())));
				continue;
			}
			for (Suggestion s : section.getValue())
			{
				body.add(card(s));
			}
		}
		rebuild();
	}

	private String emptyText(String section)
	{
		if (section.startsWith("Bossing"))
		{
			return "Kill some bosses or complete clues and RuneJourney will suggest trips that fit your time, "
				+ "favouring kill count milestones you are close to.";
		}
		if (section.startsWith("Work on"))
		{
			return "Create a goal with a weekly plan and RuneJourney will suggest what to work on with the time you have.";
		}
		if (section.startsWith("Your rates"))
		{
			return "Train a skill for " + service.rateSampleMinutes() + " minutes and RuneJourney will offer to save your XP rate as a training method "
				+ "for planning your goals.";
		}
		return "Nothing close right now. Keep going!";
	}

	private JPanel card(Suggestion s)
	{
		JPanel card = Ui.card();
		JLabel title = Ui.title(s.getTitle());
		if (s.getSkill() != null)
		{
			title.setIcon(views.skillIcon(s.getSkill()));
		}
		card.add(title);
		card.add(Ui.text(s.getDetail()));
		if (s.getProgress() >= 0)
		{
			card.add(Ui.progress(s.getProgress(), Ui.GOLD));
		}
		if (s.getSavedMethod() != null && s.getSkill() != null)
		{
			JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			actions.setOpaque(false);
			actions.add(Ui.link("Rename", () -> rename(s)));
			actions.add(Ui.small("  ·  ", Ui.MUTED));
			actions.add(Ui.link("Delete", () -> delete(s)));
			card.add(actions);
		}
		return card;
	}

	private void rename(Suggestion s)
	{
		Object name = JOptionPane.showInputDialog(this, "Rename this " + s.getSkill().getName() + " method:",
			"RuneJourney", JOptionPane.PLAIN_MESSAGE, null, null, s.getSavedMethod());
		if (name == null)
		{
			return;
		}
		String error = service.renameSavedMethod(s.getSkill(), s.getSavedMethod(), name.toString());
		if (error != null)
		{
			JOptionPane.showMessageDialog(this, error, "RuneJourney", JOptionPane.WARNING_MESSAGE);
		}
		refresh(true);
	}

	private void delete(Suggestion s)
	{
		int ok = JOptionPane.showConfirmDialog(this, "Delete your " + s.getSkill().getName() + " method \"" + s.getSavedMethod() + "\"?",
			"RuneJourney", JOptionPane.OK_CANCEL_OPTION);
		if (ok == JOptionPane.OK_OPTION)
		{
			service.deleteSavedMethod(s.getSkill(), s.getSavedMethod());
			refresh(true);
		}
	}
}

package com.runejourney.ui;

import java.awt.*;
import java.awt.event.KeyEvent;
import java.util.function.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;

final class FormDialog<T>
{
	private static final int MIN_WIDTH = 400;

	private final JDialog dialog;
	private final JScrollPane scroll;
	private final Supplier<T> build;
	private T result;

	private FormDialog(Component parent, String title, JComponent form, Supplier<T> build)
	{
		this.build = build;
		Window owner = parent == null ? null : SwingUtilities.getWindowAncestor(parent);
		dialog = new JDialog(owner, title, Dialog.ModalityType.APPLICATION_MODAL);
		dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
		dialog.setResizable(true);

		form.setBorder(new EmptyBorder(12, 12, 8, 12));
		scroll = new JScrollPane(form, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);

		JButton ok = new JButton("OK");
		ok.addActionListener(e -> submit());
		JButton cancel = new JButton("Cancel");
		cancel.addActionListener(e -> dialog.dispose());
		JPanel buttons = new JPanel(new GridLayout(1, 2, 8, 0));
		buttons.add(ok);
		buttons.add(cancel);
		JPanel south = new JPanel(new BorderLayout());
		south.setBorder(new EmptyBorder(4, 12, 12, 12));
		south.add(buttons, BorderLayout.EAST);

		JPanel content = new JPanel(new BorderLayout());
		content.add(scroll, BorderLayout.CENTER);
		content.add(south, BorderLayout.SOUTH);
		dialog.setContentPane(content);
		dialog.getRootPane().setDefaultButton(ok);
		dialog.getRootPane().registerKeyboardAction(e -> dialog.dispose(),
			KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), JComponent.WHEN_IN_FOCUSED_WINDOW);
	}

	static <T> T show(Component parent, String title, JComponent form, Supplier<T> build, Consumer<Runnable> refitHook)
	{
		FormDialog<T> d = new FormDialog<>(parent, title, form, build);
		refitHook.accept(d::refit);
		d.refit();
		d.dialog.setLocationRelativeTo(parent == null ? null : SwingUtilities.getWindowAncestor(parent));
		d.dialog.setVisible(true);
		return d.result;
	}

	private void submit()
	{
		try
		{
			result = build.get();
			dialog.dispose();
		}
		catch (IllegalArgumentException e)
		{
			JOptionPane.showMessageDialog(dialog, e.getMessage(), "RuneJourney", JOptionPane.WARNING_MESSAGE);
		}
	}

	private void refit()
	{
		scroll.getViewport().getView().revalidate();
		dialog.pack();

		GraphicsConfiguration gc = dialog.getGraphicsConfiguration();
		Rectangle screen = gc != null ? gc.getBounds() : new Rectangle(Toolkit.getDefaultToolkit().getScreenSize());
		Insets insets = gc != null ? Toolkit.getDefaultToolkit().getScreenInsets(gc) : new Insets(0, 0, 0, 0);
		int maxHeight = (int) ((screen.height - insets.top - insets.bottom) * 0.9);

		Dimension size = dialog.getSize();
		int width = Math.max(MIN_WIDTH, size.width + (size.height > maxHeight ? scroll.getVerticalScrollBar().getPreferredSize().width : 0));
		int height = Math.min(size.height, maxHeight);
		dialog.setSize(width, height);

		Rectangle b = dialog.getBounds();
		int bottom = screen.y + screen.height - insets.bottom;
		if (b.y + b.height > bottom)
		{
			dialog.setLocation(b.x, Math.max(screen.y + insets.top, bottom - b.height));
		}
		dialog.validate();
	}
}

package com.runejourney.ui;

import com.runejourney.RuneJourneyConfig;
import com.runejourney.model.*;
import com.runejourney.planner.*;
import com.runejourney.service.*;
import com.runejourney.util.Format;
import java.awt.*;
import java.time.*;
import java.util.*;
import java.util.List;
import java.util.function.LongFunction;
import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

class GoalsTab extends RefreshableTab
{
	private final JourneyService service;
	private final RuneJourneyConfig config;
	private final Views views;
	private final ItemIndex itemIndex;
	private final ItemManager itemManager;
	private final JPanel body = Ui.stack(6);
	private final JButton newGoal;
	private final List<JComboBox<?>> combos = new ArrayList<>();

	private String openGoalId;
	private int lastVersion = -1;

	@Inject
	GoalsTab(JourneyService service, RuneJourneyConfig config, Views views, ItemIndex itemIndex, ItemManager itemManager)
	{
		this.service = service;
		this.config = config;
		this.views = views;
		this.itemIndex = itemIndex;
		this.itemManager = itemManager;
		setLayout(new BorderLayout(0, 6));
		setOpaque(false);

		newGoal = Ui.button("+ New goal", this::newGoal);
		add(newGoal, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	private NewGoalDialog.Context dialogContext()
	{
		return new NewGoalDialog.Context(config.hoursPerWeek(), service.knownBosses(), service.counterValues(), itemIndex, itemManager,
			service.isBankCashKnown(), service.collectionLogPages());
	}

	private void newGoal()
	{
		NewGoalDialog.Result result = NewGoalDialog.create(this, dialogContext());
		if (result == null)
		{
			return;
		}
		if (result.getCombatAchievementPoints() != null)
		{
			service.setCombatAchievementPoints(result.getCombatAchievementPoints());
		}
		Goal goal = result.getGoal();
		String error = service.createGoal(goal);
		if (error != null)
		{
			JOptionPane.showMessageDialog(this, error, "RuneJourney", JOptionPane.WARNING_MESSAGE);
		}
		else
		{
			openGoalId = goal.getId();
		}
		refresh(true);
	}

	private void open(String id)
	{
		openGoalId = id;
		refresh(true);
	}

	@Override
	void refresh(boolean force)
	{
		int version = service.getVersion();
		if (!force && version == lastVersion)
		{
			return;
		}
		for (JComboBox<?> c : combos)
		{
			if (c.isPopupVisible())
			{
				return;
			}
		}
		lastVersion = version;
		combos.clear();
		body.removeAll();

		List<GoalProgress> goals = service.goalProgress();
		GoalProgress open = null;
		for (GoalProgress p : goals)
		{
			if (p.getGoal().getId().equals(openGoalId))
			{
				open = p;
			}
		}

		if (open != null)
		{
			newGoal.setVisible(false);
			detail(open);
		}
		else
		{
			openGoalId = null;
			newGoal.setVisible(true);
			list(goals);
		}
		rebuild();
	}

	private void list(List<GoalProgress> goals)
	{
		SessionView session = service.sessionView();
		if (session != null)
		{
			body.add(views.session(session));
		}

		boolean anyActive = false;
		for (GoalProgress p : goals)
		{
			if (!p.isComplete())
			{
				if (!anyActive)
				{
					body.add(Ui.header("Working towards"));
					anyActive = true;
				}
				body.add(summaryCard(p));
			}
		}
		if (!anyActive)
		{
			body.add(Ui.empty("What are you working towards? Create a goal such as 99 Slayer, 2,000 total or "
				+ "Max Cape and RuneJourney will build a weekly plan around your available time."));
		}

		boolean anyComplete = false;
		for (int i = goals.size() - 1; i >= 0; i--)
		{
			GoalProgress p = goals.get(i);
			if (p.isComplete())
			{
				if (!anyComplete)
				{
					body.add(Ui.header("Achieved"));
					anyComplete = true;
				}
				body.add(summaryCard(p));
			}
		}
	}

	private JPanel summaryCard(GoalProgress p)
	{
		Goal g = p.getGoal();
		JPanel card = Ui.card();
		card.add(goalTitle(g));

		if (p.isComplete())
		{
			card.add(Ui.small("Achieved " + Format.date(toDate(g.getCompletedAt())), Ui.GOOD));
		}
		else if (g.getType() == GoalType.CUSTOM)
		{
			if (g.getNotes() != null && !g.getNotes().isEmpty())
			{
				card.add(Ui.muted(g.getNotes()));
			}
			if (p.getTargetDate() != null)
			{
				card.add(Ui.small(targetText(p), Ui.MUTED));
			}
		}
		else
		{
			card.add(Ui.progress(p.getPercent(), Ui.GOLD));
			card.add(Ui.row(Ui.small(Format.percent(p.getPercent()), Color.WHITE), Ui.small(remainingText(p), Ui.MUTED)));
			JPanel status = statusLine(p);
			if (status != null)
			{
				card.add(status);
			}
			if (p.getWeekTarget() > 0)
			{
				card.add(Ui.row(Ui.small("This week", Ui.MUTED),
					Ui.small(Format.compact(p.getWeekAchieved()) + " / " + Format.compact(p.getWeekTarget()) + " XP",
						p.getWeekAchieved() >= p.getWeekTarget() ? Ui.GOOD : Color.WHITE)));
			}
			else if (p.getCountWeekTarget() > 0)
			{
				card.add(Ui.row(Ui.small("This week", Ui.MUTED),
					Ui.small(countText(g.getCounter(), p.getCountWeekAchieved(), p.getCountWeekTarget()),
						p.getCountWeekAchieved() >= p.getCountWeekTarget() ? Ui.GOOD : Color.WHITE)));
			}
		}
		Ui.clickable(card, () -> open(g.getId()));
		return card;
	}

	private static boolean showStatus(GoalProgress p)
	{
		GoalProgress.Status s = p.getStatus();
		return s == GoalProgress.Status.READY || s == GoalProgress.Status.COMPLETE || s == GoalProgress.Status.OVERDUE
			|| (p.getTargetDate() != null && s != GoalProgress.Status.NO_TARGET && s != GoalProgress.Status.TRACKING);
	}

	private JLabel goalTitle(Goal g)
	{
		boolean itemIcon = (g.getType() == GoalType.PURCHASE || g.getType() == GoalType.ITEMS) && !g.getItems().isEmpty();
		JLabel name = Ui.label(g.getName(), FontManager.getRunescapeFont(), Color.WHITE,
			Ui.TEXT_WIDTH - (itemIcon ? 44 : Skills.parse(g.getSkill()) != null ? 24 : 0));
		Skill skill = Skills.parse(g.getSkill());
		if (skill != null)
		{
			name.setIcon(views.skillIcon(skill));
			name.setIconTextGap(5);
		}
		else if ((g.getType() == GoalType.PURCHASE || g.getType() == GoalType.ITEMS) && !g.getItems().isEmpty()
			&& g.getItems().get(0).getId() > 0)
		{
			itemManager.getImage(g.getItems().get(0).getId()).addTo(name);
			name.setIconTextGap(5);
		}
		return name;
	}

	private JPanel statusLine(GoalProgress p)
	{
		if (!showStatus(p))
		{
			return p.getProjectedCompletion() == null ? null
				: Ui.row(Ui.small("Estimated finish", Ui.MUTED), Ui.small(Format.date(p.getProjectedCompletion()), Ui.MUTED));
		}
		String right = p.getTargetDate() != null ? targetText(p) : p.getProjectedCompletion() != null
			? "ETA " + Format.date(p.getProjectedCompletion()) : "";
		String left = p.getStatus() == GoalProgress.Status.NO_TARGET ? "No target date" : p.getStatus().getLabel();
		return Ui.row(Ui.small(left, statusColor(p.getStatus())), Ui.small(right, Ui.MUTED));
	}

	private static String targetText(GoalProgress p)
	{
		if (p.getDaysLeft() < 0)
		{
			return "Target " + Format.date(p.getTargetDate());
		}
		return p.getDaysLeft() + (p.getDaysLeft() == 1 ? " day left" : " days left");
	}

	private static String remainingText(GoalProgress p)
	{
		Goal g = p.getGoal();
		String time = p.getHoursRemaining() > 0 ? " · ~" + Format.hours(p.getHoursRemaining()) : "";
		if (g.getType() == GoalType.TOTAL_LEVEL)
		{
			return p.getLevelsRemaining() + " levels" + time;
		}
		if (g.getType() == GoalType.ITEMS)
		{
			return p.getItemsObtained() + " / " + p.getItemsTotal() + " items";
		}
		if (g.getType().isCounter())
		{
			if (g.isRelative())
			{
				return countText(g.getCounter(), p.getCountGained(), g.getTargetCount() - g.getStartCount()) + time;
			}
			return countText(g.getCounter(), p.getCountCurrent(), p.getCountTarget()) + time;
		}
		return Format.compact(p.getXpRemaining()) + " XP" + time;
	}

	private void detail(GoalProgress p)
	{
		Goal g = p.getGoal();
		JLabel back = Ui.link("< Back to goals", () -> open(null));
		back.setBorder(new EmptyBorder(0, 2, 0, 0));
		body.add(back);

		SessionView session = service.sessionView();
		boolean sessionHere = session != null && g.getId().equals(session.getGoalId());
		if (sessionHere)
		{
			body.add(views.session(session));
		}

		body.add(headerCard(p));
		body.add(actions(p, sessionHere));

		if (p.isComplete())
		{
			if (!g.getStory().isEmpty())
			{
				JPanel story = Ui.section("Your journey to " + g.getName());
				for (String line : g.getStory())
				{
					String[] parts = line.split("\\|", 2);
					story.add(parts.length == 2 ? Ui.stat(parts[0], parts[1]) : Ui.text(line));
				}
				body.add(story);
			}
			return;
		}
		if (g.getType() == GoalType.CUSTOM)
		{
			return;
		}
		if (g.getType() == GoalType.ITEMS)
		{
			body.add(itemChecklist(p));
			return;
		}
		if (g.getType().isCounter())
		{
			body.add(counterOverview(p));
			if (Counters.isClogPage(g.getCounter()))
			{
				body.add(clogMissing(Counters.suffix(g.getCounter())));
			}
			if (p.getCountWeekTarget() > 0)
			{
				body.add(counterWeek(p));
			}
			if (!g.getLastWeekResults().isEmpty())
			{
				body.add(lastWeek(g));
			}
			return;
		}

		body.add(overview(p));
		if (!p.getWeek().isEmpty())
		{
			body.add(thisWeek(p));
		}
		if (!g.getLastWeekResults().isEmpty())
		{
			body.add(lastWeek(g));
		}
		if (!p.getSkills().isEmpty())
		{
			body.add(trainingPlan(p));
		}
	}

	private JPanel headerCard(GoalProgress p)
	{
		Goal g = p.getGoal();
		Color color = statusColor(p.getStatus());
		JPanel card = Ui.accentCard(color);
		card.add(goalTitle(g));

		if (p.isComplete())
		{
			card.add(Ui.small("Achieved " + Format.date(toDate(g.getCompletedAt())), Ui.GOOD));
			return card;
		}
		if (g.getType() == GoalType.CUSTOM)
		{
			if (g.getNotes() != null && !g.getNotes().isEmpty())
			{
				card.add(Ui.text(g.getNotes()));
			}
			if (p.getTargetDate() != null)
			{
				card.add(Ui.stat("Target", Format.date(p.getTargetDate())));
			}
			card.add(Ui.muted("Mark this goal complete when you've achieved it."));
			return card;
		}

		card.add(Ui.progress(p.getPercent(), Ui.GOLD));
		card.add(Ui.row(Ui.small(Format.percent(p.getPercent()) + " complete", Color.WHITE), Ui.small(remainingText(p), Ui.MUTED)));
		if (showStatus(p))
		{
			card.add(Ui.small(p.getStatus().getLabel(), color));
		}
		String explanation = statusExplanation(p);
		if (!explanation.isEmpty())
		{
			card.add(Ui.text(explanation));
		}
		return card;
	}

	private static String statusExplanation(GoalProgress p)
	{
		String eta = p.getProjectedCompletion() == null ? null : Format.date(p.getProjectedCompletion());
		String basis = p.isProjectionFromPace() ? "At your current pace" : "At " + p.getAvailableHoursPerWeek() + "h/week";
		switch (p.getStatus())
		{
			case ON_TRACK:
				return eta == null ? "" : basis + " you'll finish around " + eta + ", before your target of "
					+ Format.date(p.getTargetDate()) + ".";
			case SLIGHTLY_BEHIND:
			case BEHIND:
				if (p.getRequiredHoursPerWeek() <= 0)
				{
					return "Reaching this by " + Format.date(p.getTargetDate()) + " needs about "
						+ perWeek(p) + "." + (eta != null ? " " + basis + " you'd finish around " + eta + "." : "");
				}
				return "Reaching this by " + Format.date(p.getTargetDate()) + " needs about "
					+ Format.hours(p.getRequiredHoursPerWeek()) + "/week; you planned " + p.getAvailableHoursPerWeek() + "h/week."
					+ (eta != null ? " " + basis + " you'd finish around " + eta + "." : "");
			case TRACKING:
				if (Counters.isMoney(p.getGoal().getCounter()))
				{
					return "RuneJourney will estimate a finish date once it has seen a few days of your saving"
						+ (p.getRequiredPerWeek() > 0 ? ". You need to save about " + perWeek(p) + "." : ".");
				}
				if (p.getGoal().getType() == GoalType.ITEMS)
				{
					return "Drops are random, so there's no estimate. Items tick off automatically when you get them"
						+ (p.getTargetDate() != null ? "; " + p.getDaysLeft() + " days left." : ".");
				}
				return "Keep playing and RuneJourney will project a finish date from your pace"
					+ (p.getRequiredPerWeek() > 0 ? "; you need about " + perWeek(p) + "." : ".");
			case OVERDUE:
				return "The target date has passed. Edit the goal to set a new one.";
			case READY:
				return "You have enough! Buy it on the Grand Exchange and this goal completes automatically.";
			default:
				return eta != null ? basis + " you'd finish around " + eta + "." : "";
		}
	}

	private JPanel actions(GoalProgress p, boolean sessionHere)
	{
		Goal g = p.getGoal();
		JPanel actions = new JPanel(new GridLayout(0, 2, 4, 4));
		actions.setOpaque(false);

		if (!p.isComplete())
		{
			actions.add(Ui.button("Edit", () -> edit(g.getId())));
			if (sessionHere)
			{
				actions.add(Ui.button("End session", () ->
				{
					service.endSession();
					refresh(true);
				}));
			}
			else if (g.getType() != GoalType.MONEY && g.getType() != GoalType.PURCHASE && g.getType() != GoalType.ITEMS)
			{
				JButton start = Ui.button("Start session", () ->
				{
					service.startSession(g.getId());
					refresh(true);
				});
				start.setToolTipText("Track a play session towards this goal");
				actions.add(start);
			}
			if (g.getType() == GoalType.PURCHASE)
			{
				JButton bought = Ui.button("Mark as bought", () ->
				{
					service.completeGoalManually(g.getId());
					refresh(true);
				});
				bought.setToolTipText("For purchases outside the Grand Exchange; GE purchases are picked up automatically");
				actions.add(bought);
			}
			if (g.getType() == GoalType.CUSTOM)
			{
				actions.add(Ui.button("Mark complete", () ->
				{
					service.completeGoalManually(g.getId());
					refresh(true);
				}));
			}
		}
		if (!p.isComplete())
		{
			boolean pinned = g.getId().equals(service.overlayGoalId());
			JButton pin = Ui.button(pinned ? "Unpin overlay" : "Show on overlay", () ->
			{
				service.setOverlayGoal(pinned ? null : g.getId());
				refresh(true);
			});
			pin.setToolTipText(config.showOverlay() ? "Show this goal on the in-game overlay"
				: "Show this goal on the in-game overlay (turn the overlay on in RuneJourney's settings)");
			actions.add(pin);
		}
		actions.add(Ui.button("Delete", () ->
		{
			String message = p.isComplete()
				? "Remove \"" + g.getName() + "\"? Its Journey entries are kept."
				: "Delete the goal \"" + g.getName() + "\"?";
			int ok = JOptionPane.showConfirmDialog(this, message, "RuneJourney", JOptionPane.OK_CANCEL_OPTION);
			if (ok == JOptionPane.OK_OPTION)
			{
				service.deleteGoal(g.getId());
				open(null);
			}
		}));
		return actions;
	}

	private static String countText(String key, long have, long target)
	{
		if (Counters.isMoney(key))
		{
			return Format.compact(have) + " / " + Counters.format(key, target);
		}
		return Format.number(have) + " / " + Format.number(target) + " " + Counters.unit(key);
	}

	private static String perWeek(GoalProgress p)
	{
		if (Counters.isMoney(p.getGoal().getCounter()))
		{
			return Counters.format(Counters.CASH, Math.round(p.getRequiredPerWeek())) + " a week";
		}
		double v = p.getRequiredPerWeek();
		String unit = p.getUnit() != null ? p.getUnit() : p.getGoal().getType() == GoalType.ITEMS ? "items" : "";
		return (v >= 10 ? String.valueOf(Math.round(v)) : String.format(Locale.ENGLISH, "%.1f", v)) + " " + unit + " a week";
	}

	private JPanel counterOverview(GoalProgress p)
	{
		Goal g = p.getGoal();
		JPanel card = Ui.section("Overview");
		if (!Counters.isMoney(g.getCounter()))
		{
			card.add(Ui.stat("Tracking", Counters.label(g.getCounter())));
		}
		if (g.getType() == GoalType.PURCHASE && !g.getItems().isEmpty())
		{
			GoalItem item = g.getItems().get(0);
			JLabel buying = Ui.small((g.getQuantity() > 1 ? Format.number(g.getQuantity()) + " x " : "") + item.getName(), Color.WHITE);
			if (item.getId() > 0)
			{
				itemManager.getImage(item.getId()).addTo(buying);
			}
			card.add(Ui.row(Ui.small("Buying", Ui.MUTED), buying));
			card.add(Ui.stat("Price", Counters.format(Counters.CASH, g.getTargetCount())
				+ (g.isFixedPrice() ? " (your price)" : " (GE)")));
			if (g.getQuantity() > 1 || g.getPurchasedQuantity() > 0)
			{
				card.add(Ui.stat("Bought so far", g.getPurchasedQuantity() + " / " + Math.max(1, g.getQuantity())));
			}
		}
		card.add(Ui.stat("Started", Format.date(toDate(g.getCreatedAt()))));
		String key = g.getCounter();
		if (Counters.isMoney(key))
		{
			card.add(Ui.stat(Counters.WEALTH.equals(key) ? "Net worth" : "Cash stack", Counters.format(key, p.getCountCurrent())));
			if (g.getType() == GoalType.MONEY)
			{
				card.add(Ui.stat("Target", Counters.format(key, p.getCountTarget())));
			}
			card.add(Ui.stat("Still needed", Counters.format(key, p.getCountRemaining())));
			card.add(Ui.stat("Saved since you started", (p.getCountGained() > 0 ? "+" : "") + Counters.format(key, p.getCountGained())));
		}
		else
		{
			card.add(Ui.stat("When you started", Counters.format(key, g.getStartCount())));
			card.add(Ui.stat("Now", Counters.format(key, p.getCountCurrent())));
			card.add(Ui.stat("Target", Counters.format(key, p.getCountTarget())));
			card.add(Ui.stat("Gained since", "+" + Counters.format(key, p.getCountGained())));
			card.add(Ui.stat("Remaining", Format.number(p.getCountRemaining()) + " " + p.getUnit()));
		}
		if (p.getHoursRemaining() > 0)
		{
			card.add(Ui.stat("Time remaining", "~" + Format.hours(p.getHoursRemaining())));
			if (Counters.isKc(g.getCounter()))
			{
				String boss = Counters.suffix(g.getCounter());
				double mins = service.minutesPerKill(boss);
				card.add(Ui.stat("Per kill", String.format(Locale.ENGLISH, mins < 10 ? "%.1fm" : "%.0fm", mins)
					+ (service.isPersonalKillTime(boss) ? " (yours)" : " (typical)")));
			}
		}
		if (p.getTargetDate() != null)
		{
			card.add(Ui.stat("Target date", Format.date(p.getTargetDate())));
			card.add(Ui.stat("Needed per week", perWeek(p)));
		}
		if (p.getProjectedCompletion() != null)
		{
			card.add(Ui.stat("Estimated finish", Format.date(p.getProjectedCompletion())));
		}
		if (Counters.CASH.equals(g.getCounter()))
		{
			card.add(spacer());
			card.add(Ui.muted(service.isBankCashKnown()
				? "Counts coins and platinum tokens in your inventory and bank. The bank updates whenever you open it."
				: "Open your bank once so RuneJourney can count the coins and platinum tokens in it."));
		}
		if (Counters.WEALTH.equals(g.getCounter()))
		{
			card.add(spacer());
			card.add(Ui.muted("Your bank, inventory and equipment at GE prices. The bank updates whenever you open it."));
		}
		if (Counters.CA_POINTS.equals(g.getCounter()))
		{
			card.add(spacer());
			card.add(Ui.muted("CA points go up automatically as you complete combat tasks. If the total drifts, "
				+ "edit the goal and enter your current points."));
		}
		return card;
	}

