		for (GoalItem item : initial)
		{
			chosen.addElement(new ItemIndex.Entry(item.getId(), item.getName()));
		}

		ItemRenderer renderer = new ItemRenderer();
		resultList.setCellRenderer(renderer);
		chosenList.setCellRenderer(renderer);
		resultList.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
		resultList.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getClickCount() == 2)
				{
					addSelected();
				}
			}
		});
		chosenList.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getClickCount() == 2)
				{
					removeSelected();
				}
			}
		});

		Timer debounce = new Timer(250, e -> runSearch());
		debounce.setRepeats(false);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				debounce.restart();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				debounce.restart();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				debounce.restart();
			}
		});
		search.addActionListener(e -> runSearch());

		JPanel top = new JPanel(new BorderLayout(0, 4));
		top.add(new JLabel("Search items (e.g. \"twisted bow\", \"pet\", \"ancestral\")"), BorderLayout.NORTH);
		top.add(search, BorderLayout.CENTER);
		top.add(status, BorderLayout.SOUTH);

		JPanel left = new JPanel(new BorderLayout(0, 4));
		left.add(new JLabel("Results (double-click to add)"), BorderLayout.NORTH);
		left.add(new JScrollPane(resultList), BorderLayout.CENTER);
		JButton add = new JButton("Add >");
		add.addActionListener(e -> addSelected());
		left.add(add, BorderLayout.SOUTH);

		JPanel right = new JPanel(new BorderLayout(0, 4));
		right.add(new JLabel("Your goal items"), BorderLayout.NORTH);
		right.add(new JScrollPane(chosenList), BorderLayout.CENTER);
		JButton remove = new JButton("< Remove");
		remove.addActionListener(e -> removeSelected());
		right.add(remove, BorderLayout.SOUTH);

		JPanel lists = new JPanel(new GridLayout(1, 2, 8, 0));
		lists.add(left);
		lists.add(right);

		JPanel buttons = new JPanel(new GridLayout(1, 2, 8, 0));
		JButton ok = new JButton("OK");
		ok.addActionListener(e ->
		{
			confirmed = true;
			dialog.dispose();
		});
		JButton cancel = new JButton("Cancel");
		cancel.addActionListener(e -> dialog.dispose());
		buttons.add(ok);
		buttons.add(cancel);

		JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBorder(new EmptyBorder(10, 10, 10, 10));
		content.add(top, BorderLayout.NORTH);
		content.add(lists, BorderLayout.CENTER);
		content.add(buttons, BorderLayout.SOUTH);
		dialog.setContentPane(content);
		dialog.setSize(new Dimension(560, 440));
		dialog.setLocationRelativeTo(owner);

		if (!index.isReady())
		{
			status.setText("Loading item names...");
			search.setEnabled(false);
			index.load(() ->
			{
				status.setText(" ");
				search.setEnabled(true);
				search.requestFocusInWindow();
				runSearch();
			});
		}
	}

	static List<GoalItem> show(Component parent, ItemIndex index, ItemManager itemManager, List<GoalItem> initial)
	{
		ItemSearchDialog d = new ItemSearchDialog(parent, index, itemManager, initial);
		d.dialog.setVisible(true);
		if (!d.confirmed)
		{
			return null;
		}
		List<GoalItem> items = new ArrayList<>();
		for (int i = 0; i < d.chosen.size(); i++)
		{
			ItemIndex.Entry e = d.chosen.get(i);
			items.add(new GoalItem(e.getId(), e.getName()));
		}
		return items;
	}

	private void runSearch()
	{
		results.clear();
		List<ItemIndex.Entry> found = index.search(search.getText(), 100);
		for (ItemIndex.Entry e : found)
		{
			results.addElement(e);
		}
		if (index.isReady())
		{
			status.setText(search.getText().trim().length() < 2 ? "Type at least 2 letters" : found.size() + " found");
		}
	}

	private void addSelected()
	{
		for (ItemIndex.Entry e : resultList.getSelectedValuesList())
		{
			boolean present = false;
			for (int i = 0; i < chosen.size(); i++)
			{
				present |= chosen.get(i).getName().equalsIgnoreCase(e.getName());
			}
			if (!present)
			{
				chosen.addElement(e);
			}
		}
	}

	private void removeSelected()
	{
		for (ItemIndex.Entry e : chosenList.getSelectedValuesList())
		{
			chosen.removeElement(e);
		}
	}

	private ImageIcon icon(int id, JList<?> list)
	{
		if (id <= 0)
		{
			return null;
		}
		return icons.computeIfAbsent(id, k ->
		{
			AsyncBufferedImage img = itemManager.getImage(k);
			ImageIcon icon = new ImageIcon(img);
			img.onLoaded(() ->
			{
				icon.setImage(img);
				resultList.repaint();
				chosenList.repaint();
			});
			return icon;
		});
	}

	private class ItemRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
		{
			JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
			ItemIndex.Entry e = (ItemIndex.Entry) value;
			label.setText(e.getName());
			label.setIcon(icon(e.getId(), list));
			label.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
			return label;
		}
	}
}

package com.runejourney.ui;

import com.runejourney.model.*;
import com.runejourney.service.JourneyService;
import com.runejourney.util.Format;
import java.awt.*;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import lombok.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

class JourneyTab extends RefreshableTab
{
	private static final int PAGE_DAYS = 14;
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEEE, d MMMM yyyy", Locale.ENGLISH);

	@Getter
	@RequiredArgsConstructor
	enum Filter
	{
		ALL("Everything", null, false),
		HIGHLIGHTS("Highlights only", null, true),
		SKILLS("Skills", EventType.Category.SKILLS, false),
		PVM("PvM", EventType.Category.PVM, false),
		LOOT("Drops & collection log", EventType.Category.LOOT, false),
		ACCOUNT("Quests, diaries & memories", EventType.Category.ACCOUNT, false),
		GOALS("Goals & sessions", EventType.Category.GOALS, false);

		private final String label;
		private final EventType.Category category;
		private final boolean highlightsOnly;

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final JourneyService service;
	private final Views views;
	private final ItemIndex itemIndex;
	private final ItemManager itemManager;
	private final ScreenshotWindowManager screenshotWindows;
	private final JComboBox<Filter> filterBox = new JComboBox<>(Filter.values());
	private final JPanel body = Ui.stack(4);
	private int days = PAGE_DAYS;
	private int lastEventVersion = -1;

	@Inject
	JourneyTab(JourneyService service, Views views, ItemIndex itemIndex, ItemManager itemManager,
		ScreenshotWindowManager screenshotWindows)
	{
		this.screenshotWindows = screenshotWindows;
		this.itemIndex = itemIndex;
		this.itemManager = itemManager;
		this.service = service;
		this.views = views;
		setLayout(new BorderLayout(0, 6));
		setOpaque(false);

		JButton note = Ui.button("+ Memory", this::addMemory);
		note.setToolTipText("Add your own entry: a drop, kill, pet, level, quest or anything else, on any date");
		Ui.styled(filterBox);

		JPanel controls = new JPanel(new BorderLayout(4, 0));
		controls.setOpaque(false);
		controls.add(filterBox, BorderLayout.CENTER);
		controls.add(note, BorderLayout.EAST);
		filterBox.addActionListener(e ->
		{
			days = PAGE_DAYS;
			refresh(true);
		});

		JButton gallery = Ui.button("Screenshots", screenshotWindows::open);
		gallery.setToolTipText("View, save or delete the screenshots RuneJourney has taken");
		JPanel top = new JPanel(new GridLayout(0, 1, 0, 4));
		top.setOpaque(false);
		top.add(controls);
		top.add(gallery);

		add(top, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	private void addMemory()
	{
		if (!service.isReady())
		{
			return;
		}
		MemoryDialog.Result result = MemoryDialog.show(this, itemIndex, itemManager, service.knownBosses());
		if (result != null)
		{
			service.addMemories(result.getDate(), result.getEvents(), result.getItems());
			refresh(true);
		}
	}

	@Override
	void refresh(boolean force)
	{
		int version = service.getEventVersion();
		if (!force && version == lastEventVersion)
		{
			return;
		}
		lastEventVersion = version;

		Filter filter = (Filter) filterBox.getSelectedItem();
		List<DayRecord> records = service.journeyDays(days + 1, filter.getCategory(), filter.isHighlightsOnly());
		body.removeAll();

		if (records.isEmpty())
		{
			body.add(Ui.empty("Your Journey is empty for now. Levels, drops, boss kills, quests and milestones "
				+ "will appear here automatically as you play."));
			rebuild();
			return;
		}

		for (int i = 0; i < Math.min(days, records.size()); i++)
		{
			DayRecord d = records.get(i);
			body.add(dayHeader(d));
			for (JourneyEvent e : d.getEvents())
			{
				body.add(views.event(e, d.getDate()));
			}
		}

		if (records.size() > days)
		{
			JButton more = new JButton("Show older days");
			more.addActionListener(e ->
			{
				days += PAGE_DAYS;
				refresh(true);
			});
			body.add(more);
		}
		rebuild();
	}

	private JPanel dayHeader(DayRecord d)
	{
		JPanel p = new JPanel(new GridLayout(0, 1));
		p.setOpaque(false);
		p.setBorder(new EmptyBorder(10, 2, 2, 0));
		LocalDate date = LocalDate.parse(d.getDate());
		String name = date.equals(LocalDate.now()) ? "Today" : date.equals(LocalDate.now().minusDays(1)) ? "Yesterday" : date.format(DAY);
		JLabel title = new JLabel(name);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Ui.GOLD);
		p.add(title);

		StringBuilder summary = new StringBuilder();
		if (d.getPlayMillis() > 0)
		{
			summary.append(Format.duration(d.getPlayMillis()));
		}
		if (d.getXpGained() > 0)
		{
			summary.append(summary.length() > 0 ? " · " : "").append(Format.compact(d.getXpGained())).append(" XP");
		}
		if (d.getLootValue() > 0)
		{
			summary.append(summary.length() > 0 ? " · " : "").append(Format.compact(d.getLootValue())).append(" loot");
		}
		if (summary.length() > 0)
		{
			p.add(Ui.muted(summary.toString()));
		}
		return p;
	}
}

package com.runejourney.ui;

import com.runejourney.model.*;
import com.runejourney.planner.*;
import com.runejourney.service.JourneyService;
import com.runejourney.util.Format;
import java.awt.*;
import java.text.ParseException;
import java.time.*;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;

final class MemoryDialog
{
	@Getter
	@RequiredArgsConstructor
	enum Kind
	{
		LOOT("Loot drop", EventType.DROP),
		KILL("Boss kill", EventType.BOSS_KC),
		PET("Pet", EventType.PET),
		COLLECTION_LOG("Collection log slot", EventType.COLLECTION_LOG),
		LEVEL("Level up", EventType.LEVEL),
		QUEST("Quest completed", EventType.QUEST),
		CLUE("Clue scroll", EventType.CLUE),
		OTHER("Other", EventType.NOTE);

		private final String label;
		private final EventType type;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@Value
	static class Result
	{
		LocalDate date;
		List<JourneyEvent> events;
		List<JourneyService.LootItem> items;
	}

	private final ItemIndex itemIndex;
	private final ItemManager itemManager;

	private final JComboBox<Kind> kind = new JComboBox<>(Kind.values());
	private final JButton chooseItems = new JButton("Choose item...");
	private final JLabel itemsSummary = new JLabel();
	private final JTextField quantity = new JTextField("1", 8);
	private final JTextField value = new JTextField(10);
	private final JComboBox<String> boss;
	private final JTextField killCount = new JTextField(8);
	private final JTextField killTime = new JTextField(8);
	private final JComboBox<Skill> skill = new JComboBox<>(Skills.ALL.toArray(new Skill[0]));
	private final JTextField level = new JTextField("99", 8);
	private final JComboBox<String> quest;
	private final JComboBox<String> clueTier = new JComboBox<>(Counters.CLUE_TIERS.toArray(new String[0]));
	private final JTextField title = new JTextField(18);
	private final JTextField note = new JTextField(18);
	private final JTextField date = new JTextField(LocalDate.now().toString(), 10);
	private final JTextField time = new JTextField(LocalTime.now().withSecond(0).withNano(0).toString(), 6);
	private final JCheckBox highlight = new JCheckBox("Show in highlights", true);

	private final JLabel itemsLabel = new JLabel("Item");
	private final JLabel quantityLabel = new JLabel("Quantity");
	private final JLabel valueLabel = new JLabel("Value (gp)");
	private final JLabel valueHint = new JLabel("<html><small>Filled from the GE price; change it if you like</small></html>");
	private final JLabel bossLabel = new JLabel("Boss / source");
	private final JLabel killCountLabel = new JLabel("Kill count");
	private final JLabel killTimeLabel = new JLabel("Kill time");
	private final JLabel skillLabel = new JLabel("Skill");
	private final JLabel levelLabel = new JLabel("Level");
	private final JLabel questLabel = new JLabel("Quest");
	private final JLabel tierLabel = new JLabel("Tier");
	private final JLabel titleLabel = new JLabel("What happened?");
	private final JPanel form = new JPanel(new GridBagLayout());
	private final Map<JComponent, JComponent> rowLabels = new HashMap<>();
	private Runnable refit = () ->
	{
	};
	private int row;
	private List<GoalItem> items = new ArrayList<>();

	private MemoryDialog(ItemIndex itemIndex, ItemManager itemManager, List<String> bosses)
	{
		this.itemIndex = itemIndex;
		this.itemManager = itemManager;
		boss = new JComboBox<>(bosses.toArray(new String[0]));
		boss.setEditable(true);
		boss.setSelectedItem("");
		skill.setRenderer(new SkillRenderer());
		quest = new JComboBox<>(Arrays.stream(Quest.values()).map(Quest::getName).sorted().toArray(String[]::new));
		quest.setEditable(true);

		addRow(new JLabel("Type"), kind);
		addRow(itemsLabel, chooseItems);
		addRow(new JLabel(""), itemsSummary);
		addRow(quantityLabel, quantity);
		addRow(valueLabel, value);
		addRow(new JLabel(""), valueHint);
		addRow(bossLabel, boss);
		addRow(killCountLabel, killCount);
		addRow(killTimeLabel, killTime);
		addRow(skillLabel, skill);
		addRow(levelLabel, level);
		addRow(questLabel, quest);
		addRow(tierLabel, clueTier);
		addRow(titleLabel, title);
		addRow(new JLabel("Note"), note);
		addRow(new JLabel("Date"), date);
		addRow(new JLabel("Time"), time);
		addRow(new JLabel(""), highlight);

		killTime.setToolTipText("Optional, e.g. 1:23 or 17:42.60");
		chooseItems.addActionListener(e -> pickItems());
		quantity.addActionListener(e -> updateValue());
		quantity.addFocusListener(new java.awt.event.FocusAdapter()
		{
			@Override
			public void focusLost(java.awt.event.FocusEvent e)
			{
				updateValue();
			}
		});
		kind.addActionListener(e -> updateFields());
		updateFields();
		updateItems();
	}

	private void addRow(JComponent label, JComponent field)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridy = row++;
		c.insets = new Insets(3, 3, 3, 3);
		c.anchor = GridBagConstraints.WEST;
		c.gridx = 0;
		form.add(label, c);
		c.gridx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.weightx = 1;
		form.add(field, c);
		rowLabels.put(field, label);
	}

	private void show(boolean visible, JComponent... components)
	{
		for (JComponent c : components)
		{
			c.setVisible(visible);
			JComponent label = rowLabels.get(c);
			if (label != null)
			{
				label.setVisible(visible);
			}
		}
	}

	private void updateFields()
	{
		Kind k = (Kind) kind.getSelectedItem();
		boolean itemKind = k == Kind.LOOT || k == Kind.PET || k == Kind.COLLECTION_LOG;
		show(itemKind, itemsLabel, chooseItems, itemsSummary);
		show(k == Kind.LOOT, quantityLabel, quantity, valueHint);
		show(k == Kind.LOOT || k == Kind.CLUE, valueLabel, value);
		show(itemKind || k == Kind.KILL, bossLabel, boss);
		show(k == Kind.LOOT || k == Kind.KILL || k == Kind.PET, killCountLabel, killCount);
		show(k == Kind.KILL, killTimeLabel, killTime);
		show(k == Kind.LEVEL, skillLabel, skill, levelLabel, level);
		show(k == Kind.QUEST, questLabel, quest);
		show(k == Kind.CLUE, tierLabel, clueTier);
		show(k == Kind.OTHER, titleLabel, title);
		bossLabel.setText(k == Kind.KILL ? "Boss" : "Source (optional)");
		chooseItems.setText(k == Kind.LOOT ? "Choose item(s)..." : "Choose item...");
		valueLabel.setText(k == Kind.CLUE ? "Loot value (gp)" : "Value (gp)");
		refit.run();
	}

	private void pickItems()
	{
		List<GoalItem> picked = ItemSearchDialog.show(form, itemIndex, itemManager, items);
		if (picked != null)
		{
			Kind k = (Kind) kind.getSelectedItem();
			items = k == Kind.LOOT || picked.isEmpty() ? picked : picked.subList(picked.size() - 1, picked.size());
			updateItems();
			updateValue();
			refit.run();
		}
	}

	private void updateItems()
	{
		if (items.isEmpty())
		{
			itemsSummary.setText("<html><small>Nothing chosen yet</small></html>");
			return;
		}
		String names = items.stream().limit(4).map(GoalItem::getName).collect(Collectors.joining(", "));
		if (items.size() > 4)
		{
			names += " +" + (items.size() - 4) + " more";
		}
		itemsSummary.setText("<html><small>" + Ui.escape(names) + "</small></html>");
	}

	private long quantityValue()
	{
		try
		{
			return Math.max(1, QuantityFormatter.parseQuantity(quantity.getText().trim()));
		}
		catch (ParseException | NumberFormatException e)
		{
			return 1;
		}
	}

	private void updateValue()
	{
		long qty = items.size() == 1 ? quantityValue() : 1;
		long total = 0;
		for (GoalItem item : items)
		{
			total += itemIndex.price(item.getId()) * qty;
		}
		value.setText(total > 0 ? Format.number(total) : "");
	}

	static Result show(Component parent, ItemIndex itemIndex, ItemManager itemManager, List<String> bosses)
	{
		MemoryDialog d = new MemoryDialog(itemIndex, itemManager, bosses);
		return FormDialog.show(parent, "Add a memory", d.form, d::build, r -> d.refit = r);
	}

	private Result build()
	{
		Kind k = (Kind) kind.getSelectedItem();
		LocalDate day = GoalPlanner.parseDate(date.getText().trim());
		if (day == null || day.isAfter(LocalDate.now()))
		{
			throw new IllegalArgumentException("Enter the date as YYYY-MM-DD (today or earlier).");
		}
		LocalTime at;
		try
		{
			at = LocalTime.parse(time.getText().trim());
		}
		catch (DateTimeParseException e)
		{
			throw new IllegalArgumentException("Enter the time as HH:MM, e.g. 18:30.");
		}
		long when = LocalDateTime.of(day, at).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();

		String source = text(boss.getSelectedItem());
		Long kc = optionalNumber(killCount.getText(), "Enter the kill count as a number, or leave it blank.");
		String extra = text(note.getText());
		List<JourneyEvent> events = new ArrayList<>();
		List<JourneyService.LootItem> obtained = new ArrayList<>();

		switch (k)
		{
			case LOOT:
			case PET:
			case COLLECTION_LOG:
			{
				if (items.isEmpty())
				{
					throw new IllegalArgumentException("Choose the item.");
				}
				long qty = k == Kind.LOOT && items.size() == 1 ? quantityValue() : 1;
				Long total = k == Kind.LOOT ? optionalNumber(value.getText(), "Enter the value in gp, or leave it blank.") : null;
				for (GoalItem item : items)
				{
					long itemValue = total == null ? itemIndex.price(item.getId()) * qty
						: items.size() == 1 ? total : itemIndex.price(item.getId());
					String name = k == Kind.PET ? "Pet: " + item.getName()
						: qty > 1 ? Format.number(qty) + " x " + item.getName() : item.getName();
					List<String> parts = new ArrayList<>();
					if (k == Kind.LOOT && itemValue > 0)
					{
						parts.add(Format.compact(itemValue) + " gp");
					}
					if (source != null)
					{
						parts.add(source + (kc != null ? " · KC " + Format.number(kc) : ""));
					}
					else if (kc != null)
					{
						parts.add("KC " + Format.number(kc));
					}
					events.add(event(k.getType(), name, join(parts, extra), when, null, itemValue));
					obtained.add(new JourneyService.LootItem(item.getId(), item.getName(), (int) qty, itemValue));
				}
				break;
			}
			case KILL:
			{
				if (source == null)
				{
					throw new IllegalArgumentException("Choose or type the boss.");
				}
				String name = kc != null ? Format.number(kc) + " " + source + " KC" : "Killed " + source;
				List<String> parts = new ArrayList<>();
				String t = text(killTime.getText());
				if (t != null)
				{
					parts.add("Kill time " + t);
				}
				events.add(event(k.getType(), name, join(parts, extra), when, null, kc != null ? kc : 0));
				break;
			}
			case LEVEL:
			{
				Skill s = (Skill) skill.getSelectedItem();
				Long lvl = optionalNumber(level.getText(), "Enter the level as a number.");
				if (lvl == null || lvl < 2 || lvl > Experience.MAX_VIRT_LEVEL)
				{
					throw new IllegalArgumentException("Enter a level between 2 and " + Experience.MAX_VIRT_LEVEL + ".");
				}
				events.add(event(k.getType(), "Level " + lvl + " " + s.getName(), extra, when, s.name(), lvl));
				break;
			}
			case QUEST:
			{
				String q = text(quest.getSelectedItem());
				if (q == null)
				{
					throw new IllegalArgumentException("Choose or type the quest.");
				}
				events.add(event(k.getType(), "Completed " + q, extra, when, null, 0));
				break;
			}
			case CLUE:
			{
				String tier = (String) clueTier.getSelectedItem();
				Long loot = optionalNumber(value.getText(), "Enter the loot value in gp, or leave it blank.");
				List<String> parts = new ArrayList<>();
				if (loot != null && loot > 0)
				{
					parts.add("Loot " + Format.compact(loot) + " gp");
				}
				events.add(event(k.getType(), tier + " clue", join(parts, extra), when, null, loot != null ? loot : 0));
				break;
			}
			default:
			{
				String t = text(title.getText());
				if (t == null)
				{
					throw new IllegalArgumentException("Describe what happened.");
				}
				events.add(event(k.getType(), t.length() > 200 ? t.substring(0, 200) : t, extra, when, null, 0));
			}
		}
		return new Result(day, events, obtained);
	}

	private JourneyEvent event(EventType type, String name, String detail, long when, String skillKey, long val)
	{
		return new JourneyEvent(when, type, name, detail, skillKey, null, highlight.isSelected(), val);
	}

	private static String join(List<String> parts, String note)
	{
		List<String> all = new ArrayList<>(parts);
		if (note != null)
		{
			all.add(note);
		}
		return all.isEmpty() ? null : String.join(" · ", all);
	}

	private static String text(Object o)
	{
		if (o == null)
		{
			return null;
		}
		String s = o.toString().trim();
		return s.isEmpty() ? null : s;
	}

	private static Long optionalNumber(String text, String error)
	{
		String t = text.trim().replace(",", "");
		if (t.isEmpty())
		{
			return null;
		}
		try
		{
			return QuantityFormatter.parseQuantity(t);
		}
		catch (ParseException | NumberFormatException e)
		{
			throw new IllegalArgumentException(error);
		}
	}
}

package com.runejourney.ui;

import com.runejourney.model.*;
import com.runejourney.planner.*;
import com.runejourney.util.Format;
import java.awt.*;
import java.text.ParseException;
import java.time.LocalDate;
import java.util.*;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.*;
import lombok.Value;
import net.runelite.api.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;

final class NewGoalDialog
{
	@Value
	static class Context
	{
		int defaultHours;
		List<String> bosses;
		Map<String, Long> counters;
		ItemIndex itemIndex;
		ItemManager itemManager;
		boolean bankCashKnown;
		Map<String, int[]> clogPages;
	}

	@Value
	static class Result
	{
		Goal goal;
		Long combatAchievementPoints;
	}

	private final Context ctx;
	private final Goal existing;

	private final JComboBox<GoalType> type = new JComboBox<>(GoalType.values());
	private final JComboBox<Skill> skill = new JComboBox<>(Skills.ALL.toArray(new Skill[0]));
	private final JComboBox<String> boss;
	private final JComboBox<String> clueTier = new JComboBox<>();
	private final JComboBox<String> clogPage = new JComboBox<>();
	private final JTextField target = new JTextField("99", 10);
	private final JCheckBox relative = new JCheckBox("more from now");
	private final JTextField caPoints = new JTextField(10);
	private final JButton chooseItems = new JButton("Choose items...");
	private final JLabel itemsSummary = new JLabel();
	private final JTextField name = new JTextField(16);
	private final JTextField date = new JTextField(10);
	private final JTextField hours = new JTextField(10);
	private final JTextField notes = new JTextField(16);
	private final JTextField quantity = new JTextField("1", 10);
	private final JTextField price = new JTextField(10);
	private List<GoalItem> items = new ArrayList<>();

	private final JLabel skillLabel = new JLabel("Skill");
	private final JLabel bossLabel = new JLabel("Boss / activity");
	private final JLabel tierLabel = new JLabel("Clue tier");
	private final JLabel pageLabel = new JLabel("Log page");
	private final JLabel targetLabel = new JLabel("Target");
	private final JLabel relativeLabel = new JLabel("");
	private final JLabel currentHint = new JLabel();
	private final JLabel caLabel = new JLabel("Your CA points now");
	private final JLabel caHint = new JLabel("<html><small>The game doesn't share this, so enter it once<br>(Combat Achievements overview).</small></html>");
	private final JLabel itemsLabel = new JLabel("Items");
	private final JLabel nameLabel = new JLabel("Name");
	private final JLabel notesLabel = new JLabel("Notes");
	private final JLabel hoursLabel = new JLabel("Hours per week");
	private final JLabel quantityLabel = new JLabel("Quantity");
	private final JLabel priceLabel = new JLabel("Price each (gp)");
	private final JLabel priceHint = new JLabel("<html><small>From the GE; kept up to date unless you change it</small></html>");
	private final JLabel hoursHint;
	private final JPanel form = new JPanel(new GridBagLayout());
	private final Map<JComponent, JComponent> rowLabels = new HashMap<>();
	private Runnable refit = () ->
	{
	};
	private int row;

	private NewGoalDialog(Context ctx, Goal existing)
	{
		this.ctx = ctx;
		this.existing = existing;
		hoursHint = new JLabel("<html><small>Blank = your default (" + ctx.getDefaultHours() + "h)</small></html>");

		skill.setRenderer(new SkillRenderer());
		boss = new JComboBox<>(ctx.getBosses().toArray(new String[0]));
		boss.setEditable(true);
		clueTier.addItem(Counters.ALL_TIERS);
		Counters.CLUE_TIERS.forEach(clueTier::addItem);

		addRow(new JLabel("Goal type"), type);
		addRow(skillLabel, skill);
		addRow(bossLabel, boss);
		addRow(tierLabel, clueTier);
		addRow(pageLabel, clogPage);
		addRow(itemsLabel, chooseItems);
		addRow(new JLabel(""), itemsSummary);
		addRow(quantityLabel, quantity);
		addRow(priceLabel, price);
		addRow(new JLabel(""), priceHint);
		addRow(caLabel, caPoints);
		addRow(new JLabel(""), caHint);
		addRow(targetLabel, target);
		addRow(relativeLabel, relative);
		addRow(new JLabel(""), currentHint);
		addRow(nameLabel, name);
		addRow(new JLabel("Target date"), date);
		addRow(new JLabel(""), new JLabel("<html><small>Optional, YYYY-MM-DD, e.g. " + LocalDate.now().plusMonths(3) + "</small></html>"));
		addRow(hoursLabel, hours);
		addRow(new JLabel(""), hoursHint);
		addRow(notesLabel, notes);

		Long ca = ctx.getCounters().get(Counters.CA_POINTS);
		if (ca != null && ca > 0)
		{
			caPoints.setText(String.valueOf(ca));
		}
		chooseItems.addActionListener(e -> pickItems());
		quantity.addActionListener(e -> updateHint());
		boss.addActionListener(e -> updateHint());
		clueTier.addActionListener(e -> updateHint());
		ctx.getClogPages().keySet().forEach(clogPage::addItem);
		clogPage.addActionListener(e -> updateHint());
		relative.addActionListener(e -> updateHint());

		if (existing != null)
		{
			type.setSelectedItem(existing.getType());
			type.setEnabled(false);
		}
		type.addActionListener(e -> updateFields(true));
		updateFields(existing == null);
		if (existing != null)
		{
			fill(existing);
		}
		updateItemsSummary();
		updateHint();
	}

	private void addRow(JComponent label, JComponent field)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridy = row++;
		c.insets = new Insets(3, 3, 3, 3);
		c.anchor = GridBagConstraints.WEST;
		c.gridx = 0;
		form.add(label, c);
		c.gridx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.weightx = 1;
		form.add(field, c);
		rowLabels.put(field, label);
	}

	private void pickItems()
	{
		List<GoalItem> picked = ItemSearchDialog.show(form, ctx.getItemIndex(), ctx.getItemManager(), items);
		if (picked != null)
		{
			boolean purchase = type.getSelectedItem() == GoalType.PURCHASE;
			items = purchase && picked.size() > 1 ? new ArrayList<>(picked.subList(picked.size() - 1, picked.size())) : picked;
			if (purchase && !items.isEmpty())
			{
				long p = ctx.getItemIndex().price(items.get(0).getId());
				price.setText(p > 0 ? Format.number(p) : "");
			}
			updateItemsSummary();
			updateHint();
			refit.run();
		}
	}

	private void updateItemsSummary()
	{
		if (items.isEmpty())
		{
			itemsSummary.setText("<html><small>No items chosen yet</small></html>");
			return;
		}
		String names = items.stream().limit(4).map(GoalItem::getName).collect(Collectors.joining(", "));
		if (items.size() > 4)
		{
			names += " +" + (items.size() - 4) + " more";
		}
		itemsSummary.setText("<html><small>" + Ui.escape(names) + "</small></html>");
	}

	private String counterKey()
	{
		GoalType t = (GoalType) type.getSelectedItem();
		switch (t)
		{
			case BOSS_KC:
				Object b = boss.getSelectedItem();
				return b == null || b.toString().trim().isEmpty() ? null : Counters.kc(b.toString().trim());
			case CLUES:
				return Counters.clues((String) clueTier.getSelectedItem());
			case COMBAT_ACHIEVEMENTS:
				return Counters.CA_POINTS;
			case COMBAT_TASKS:
				return Counters.CA_TASKS;
			case QUEST_POINTS:
				return Counters.QUEST_POINTS;
			case COLLECTION_LOG:
				return Counters.COLLECTION_LOG;
			case MONEY:
			case PURCHASE:
				return Counters.CASH;
			case NET_WORTH:
				return Counters.WEALTH;
			case CLOG_CATEGORY:
			{
				Object page = clogPage.getSelectedItem();
				return page == null ? null : Counters.clogPage(page.toString());
			}
			default:
				return null;
		}
	}

	private void updateHint()
	{
		String key = counterKey();
		GoalType t = (GoalType) type.getSelectedItem();
		if (t == GoalType.CLOG_CATEGORY && key == null)
		{
			currentHint.setText("<html><small>Open pages in your collection log in-game<br>and they'll appear here</small></html>");
			return;
		}
		if (key == null || t == GoalType.COMBAT_ACHIEVEMENTS)
		{
			currentHint.setText("");
			return;
		}
		Long have = ctx.getCounters().get(key);
		if (t == GoalType.CLOG_CATEGORY)
		{
			int[] page = ctx.getClogPages().get(Counters.suffix(key));
			currentHint.setText(page == null ? "" : "<html><small>" + page[0] + " / " + page[1] + " items obtained</small></html>");
			return;
		}
		if (Counters.WEALTH.equals(key))
		{
			currentHint.setText("<html><small>" + (have == null
				? "Open your bank once so RuneJourney can value it"
				: "Your net worth is " + Counters.format(key, have)) + "</small></html>");
			return;
		}
		if (Counters.CASH.equals(key))
		{
			String cash = "You have " + Counters.format(key, have == null ? 0 : have) + " in coins and platinum tokens";
			if (!ctx.isBankCashKnown())
			{
				cash += "<br>(open your bank once so your banked coins count)";
			}
			currentHint.setText("<html><small>" + cash + "</small></html>");
			return;
		}
		currentHint.setText("<html><small>You have " + (have == null ? "none recorded yet" : Format.number(have))
			+ (t == GoalType.BOSS_KC && have == null ? " (updates on your next kill)" : "") + "</small></html>");
	}

	private void fill(Goal g)
	{
		name.setText(g.getName().equals(defaultName(g)) ? "" : g.getName());
		date.setText(g.getTargetDate() == null ? "" : g.getTargetDate());
		hours.setText(g.getHoursPerWeek() > 0 ? String.valueOf(g.getHoursPerWeek()) : "");
		notes.setText(g.getNotes() == null ? "" : g.getNotes());
		switch (g.getType())
		{
			case SKILL:
			{
				Skill s = Skills.parse(g.getSkill());
				if (s != null)
				{
					skill.setSelectedItem(s);
				}
				int level = Experience.getLevelForXp((int) Math.min(g.getTargetXp(), Experience.MAX_SKILL_XP));
				target.setText(Skills.xpForLevel(level) == g.getTargetXp() ? String.valueOf(level) : Format.compact(g.getTargetXp()));
				break;
			}
			case TOTAL_LEVEL:
			case BASE_LEVEL:
				target.setText(String.valueOf(g.getTargetLevel()));
				break;
			case ITEMS:
				items = new ArrayList<>(g.getItems());
				break;
			case PURCHASE:
				items = new ArrayList<>(g.getItems());
				quantity.setText(String.valueOf(Math.max(1, g.getQuantity())));
				price.setText(Format.number(g.getTargetCount() / Math.max(1, g.getQuantity())));
				break;
			default:
				if (g.getType().isCounter())
				{
					if (Counters.isKc(g.getCounter()))
					{
						boss.setSelectedItem(Counters.suffix(g.getCounter()));
					}
					else if (Counters.isClues(g.getCounter()))
					{
						clueTier.setSelectedItem(Counters.suffix(g.getCounter()));
					}
					else if (Counters.isClogPage(g.getCounter()))
					{
						clogPage.setSelectedItem(Counters.suffix(g.getCounter()));
						clogPage.setEnabled(false);
					}
					boss.setEnabled(false);
					clueTier.setEnabled(false);
					relative.setSelected(g.isRelative());
					target.setText(String.valueOf(g.isRelative() ? g.getTargetCount() - g.getStartCount() : g.getTargetCount()));
				}
		}
	}

	private void updateFields(boolean resetTarget)
	{
		GoalType t = (GoalType) type.getSelectedItem();
		boolean counter = t.isCounter();
		boolean hasTarget = t == GoalType.SKILL || t == GoalType.TOTAL_LEVEL || t == GoalType.BASE_LEVEL || counter;
		boolean custom = t == GoalType.CUSTOM;

		show(t == GoalType.SKILL, skillLabel, skill);
		show(t == GoalType.BOSS_KC, bossLabel, boss);
		show(t == GoalType.CLUES, tierLabel, clueTier);
		boolean money = t == GoalType.MONEY || t == GoalType.PURCHASE || t == GoalType.NET_WORTH;
		boolean clog = t == GoalType.CLOG_CATEGORY;
		show(clog, pageLabel, clogPage);
		show(t == GoalType.ITEMS || t == GoalType.PURCHASE, itemsLabel, chooseItems, itemsSummary);
		show(t == GoalType.PURCHASE, quantityLabel, quantity, priceLabel, price, priceHint);
		show(t == GoalType.COMBAT_ACHIEVEMENTS, caLabel, caPoints, caHint);
		show(hasTarget && t != GoalType.PURCHASE && !clog, targetLabel, target);
		show(counter && !money && !clog, relativeLabel, relative);
		show(counter, currentHint);
		show(custom, notesLabel, notes);
		show(t.isSkilling() || counter, hoursLabel, hours, hoursHint);
		nameLabel.setText(custom ? "Name" : "Name (optional)");

		if (resetTarget)
		{
			switch (t)
			{
				case SKILL:
					target.setText("99");
					break;
				case TOTAL_LEVEL:
					target.setText("2000");
					break;
				case BASE_LEVEL:
					target.setText("90");
					break;
				case BOSS_KC:
					target.setText("100");
					relative.setSelected(false);
					break;
				case CLUES:
					target.setText("100");
					relative.setSelected(true);
					break;
				case COMBAT_ACHIEVEMENTS:
					target.setText("1000");
					relative.setSelected(false);
					break;
				case COMBAT_TASKS:
					target.setText("20");
					relative.setSelected(true);
					break;
				case QUEST_POINTS:
				case COLLECTION_LOG:
					target.setText("");
					relative.setSelected(false);
					break;
				case MONEY:
					target.setText("100m");
					relative.setSelected(false);
					break;
				case NET_WORTH:
					target.setText("1b");
					relative.setSelected(false);
					break;
				case CLOG_CATEGORY:
					relative.setSelected(false);
					break;
				case PURCHASE:
					relative.setSelected(false);
					break;
				default:
					break;
			}
		}
		switch (t)
		{
			case SKILL:
				targetLabel.setText("Level or XP");
				break;
			case TOTAL_LEVEL:
				targetLabel.setText("Total level");
				break;
			case BASE_LEVEL:
				targetLabel.setText("Base level");
				break;
			case BOSS_KC:
				targetLabel.setText("Kill count");
				break;
			case CLUES:
				targetLabel.setText("Clues");
				break;
			case COMBAT_ACHIEVEMENTS:
				targetLabel.setText("Target points");
				break;
			case COMBAT_TASKS:
				targetLabel.setText("Tasks");
				break;
			case QUEST_POINTS:
				targetLabel.setText("Quest points");
				break;
			case COLLECTION_LOG:
				targetLabel.setText("Log slots");
				break;
			case MONEY:
			case NET_WORTH:
				targetLabel.setText("Amount (e.g. 500m)");
				break;
			default:
				break;
		}
		updateHint();
		refit.run();
	}

	private void show(boolean visible, JComponent... components)
	{
		for (JComponent c : components)
		{
			c.setVisible(visible);
			JComponent label = rowLabels.get(c);
			if (label != null)
			{
				label.setVisible(visible);
			}
		}
	}

	static Result create(Component parent, Context ctx)
	{
		return show(parent, new NewGoalDialog(ctx, null), "New goal");
	}

	static Result edit(Component parent, Context ctx, Goal goal)
	{
		return show(parent, new NewGoalDialog(ctx, goal), "Edit goal");
	}

	private static Result show(Component parent, NewGoalDialog d, String title)
	{
		return FormDialog.show(parent, title, d.form, d::build, r -> d.refit = r);
	}

	private Result build()
	{
		GoalType t = (GoalType) type.getSelectedItem();
		Goal g = new Goal();
		if (existing != null)
		{
			g.setId(existing.getId());
		}
		g.setType(t);
		String customName = name.getText().trim();
		Long ca = null;

		switch (t)
		{
			case SKILL:
			{
				Skill s = (Skill) skill.getSelectedItem();
				long value = parseNumber(target.getText(), "Enter a level (e.g. 99) or an XP amount (e.g. 50m).");
				g.setSkill(s.name());
				if (value <= Experience.MAX_VIRT_LEVEL)
				{
					if (value < 2)
					{
						throw new IllegalArgumentException("Enter a level between 2 and " + Experience.MAX_VIRT_LEVEL + ".");
					}
					g.setTargetXp(Skills.xpForLevel((int) value));
				}
				else
				{
					if (value > Experience.MAX_SKILL_XP)
					{
						throw new IllegalArgumentException("The maximum XP in a skill is 200m.");
					}
					g.setTargetXp(value);
				}
				break;
			}
			case TOTAL_LEVEL:
			{
				long value = parseNumber(target.getText(), "Enter a total level.");
				if (value < 33 || value > Skills.MAX_TOTAL_LEVEL)
				{
					throw new IllegalArgumentException("Enter a total level up to " + Skills.MAX_TOTAL_LEVEL + ".");
				}
				g.setTargetLevel((int) value);
				break;
			}
			case BASE_LEVEL:
			{
				long value = parseNumber(target.getText(), "Enter a base level.");
				if (value < 2 || value > Experience.MAX_REAL_LEVEL)
				{
					throw new IllegalArgumentException("Enter a base level between 2 and 99.");
				}
				g.setTargetLevel((int) value);
				break;
			}
			case MAX_CAPE:
				g.setTargetLevel(Experience.MAX_REAL_LEVEL);
				break;
			case ITEMS:
				if (items.isEmpty())
				{
					throw new IllegalArgumentException("Choose at least one item.");
				}
				g.setItems(new ArrayList<>(items));
				break;
			case CUSTOM:
				if (customName.isEmpty())
				{
					throw new IllegalArgumentException("Give your goal a name.");
				}
				g.setNotes(notes.getText().trim());
				break;
			case CLOG_CATEGORY:
			{
				String key = counterKey();
				int[] page = key == null ? null : ctx.getClogPages().get(Counters.suffix(key));
				if (page == null)
				{
					throw new IllegalArgumentException("Open the page in your collection log in-game first, then choose it here.");
				}
				if (existing == null && page[0] >= page[1])
				{
					throw new IllegalArgumentException("You've already completed that page!");
				}
				g.setCounter(key);
				g.setTargetCount(page[1]);
				break;
			}
			case PURCHASE:
			{
				if (items.isEmpty())
				{
					throw new IllegalArgumentException("Choose the item you want to buy.");
				}
				long qty = parseNumber(quantity.getText(), "Enter how many you want to buy.");
				if (qty < 1)
				{
					throw new IllegalArgumentException("Enter a quantity of at least 1.");
				}
				long each = parseNumber(price.getText().replace(",", ""), "Enter the price in gp (e.g. 1.2b).");
				if (each < 1)
				{
					throw new IllegalArgumentException("That item has no GE price, so enter what you expect to pay.");
				}
				GoalItem item = items.get(0);
				g.setItems(new ArrayList<>(items.subList(0, 1)));
				g.setQuantity((int) Math.min(Integer.MAX_VALUE, qty));
				g.setCounter(Counters.CASH);
				g.setTargetCount(each * qty);
				g.setFixedPrice(ctx.getItemIndex().isReady()
					? each != ctx.getItemIndex().price(item.getId())
					: existing != null && existing.isFixedPrice());
				break;
			}
			default:
			{
				String key = counterKey();
				if (key == null)
				{
					throw new IllegalArgumentException("Choose a boss or activity.");
				}
				long value = parseNumber(target.getText(), "Enter how many " + Counters.unit(key) + " you're aiming for.");
				if (value < 1)
				{
					throw new IllegalArgumentException("Enter a target of at least 1.");
				}
				if (t == GoalType.COMBAT_ACHIEVEMENTS && !caPoints.getText().trim().isEmpty())
				{
					ca = parseNumber(caPoints.getText(), "Enter your current CA points as a number, or leave it blank.");
				}
				g.setCounter(key);
				g.setTargetCount(value);
				g.setRelative(relative.isSelected());
				if (!relative.isSelected())
				{
					Long have = t == GoalType.COMBAT_ACHIEVEMENTS ? ca : ctx.getCounters().get(key);
					if (have != null && have >= value && existing == null)
					{
						throw new IllegalArgumentException("You already have " + Format.number(have) + ". Choose a higher target, "
							+ "or tick \"more from now\".");
					}
				}
			}
		}
		g.setName(customName.isEmpty() ? defaultName(g) : customName);

		String dateText = date.getText().trim();
		if (!dateText.isEmpty())
		{
			LocalDate d = GoalPlanner.parseDate(dateText);
			if (d == null)
			{
				throw new IllegalArgumentException("Enter the target date as YYYY-MM-DD.");
			}
			if (!d.isAfter(LocalDate.now()))
			{
				throw new IllegalArgumentException("The target date needs to be in the future.");
			}
			g.setTargetDate(d.toString());
		}

		String hoursText = hours.getText().trim();
		if (!hoursText.isEmpty() && (t.isSkilling() || t.isCounter()))
		{
			long h = parseNumber(hoursText, "Enter hours per week as a number, or leave it blank.");
			if (h < 1 || h > 168)
			{
				throw new IllegalArgumentException("Hours per week must be between 1 and 168.");
			}
			g.setHoursPerWeek((int) h);
		}
		return new Result(g, ca);
	}

	private static String defaultName(Goal g)
	{
		switch (g.getType())
		{
			case SKILL:
			{
				Skill s = Skills.parse(g.getSkill());
				if (s == null)
				{
					return "";
				}
				int level = Experience.getLevelForXp((int) Math.min(g.getTargetXp(), Experience.MAX_SKILL_XP));
				return Skills.xpForLevel(level) == g.getTargetXp()
					? level + " " + s.getName()
					: Format.compact(g.getTargetXp()) + " " + s.getName() + " XP";
			}
			case TOTAL_LEVEL:
				return Format.number(g.getTargetLevel()) + " Total level";
			case BASE_LEVEL:
				return "Base " + g.getTargetLevel();
			case MAX_CAPE:
				return "Max Cape";
			case ITEMS:
			{
				if (g.getItems().isEmpty())
				{
					return "Obtain items";
				}
				String first = g.getItems().get(0).getName();
				return g.getItems().size() == 1 ? first : first + " + " + (g.getItems().size() - 1) + " more";
			}
			case MONEY:
				return "Save " + Counters.format(Counters.CASH, g.getTargetCount());
			case NET_WORTH:
				return Counters.format(Counters.WEALTH, g.getTargetCount()) + " net worth";
			case CLOG_CATEGORY:
				return g.getCounter() == null ? "Collection log page" : "Complete the " + Counters.suffix(g.getCounter()) + " log";
			case PURCHASE:
				if (g.getItems().isEmpty())
				{
					return "Purchase";
				}
				return "Buy " + (g.getQuantity() > 1 ? Format.number(g.getQuantity()) + " x " : "") + g.getItems().get(0).getName();
			default:
				if (g.getType().isCounter() && g.getCounter() != null)
				{
					long n = g.isRelative() && g.getStartCount() > 0 ? g.getTargetCount() - g.getStartCount() : g.getTargetCount();
					String label = Counters.label(g.getCounter());
					if (Counters.isClues(g.getCounter()) && Counters.ALL_TIERS.equals(Counters.suffix(g.getCounter())))
					{
						label = "clue scrolls";
					}
					return (g.isRelative() ? "+" : "") + Format.number(n) + " " + label;
				}
				return "";
		}
	}

	private static long parseNumber(String text, String error)
	{
		try
		{
			return QuantityFormatter.parseQuantity(text.trim());
		}
		catch (ParseException | NumberFormatException e)
		{
			throw new IllegalArgumentException(error);
		}
	}
}

